const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db;try{db=validateWorkspace(JSON.parse(localStorage.getItem(STORAGE_KEY)))}catch{db=seed()}
let selected=db.settings.selectedPatient||db.patients[0]?.id,view='',search='',filter='全部',range=7,detailTab='overview',assistantRole='医护助手',chat=[],emg=null,gameHits=0;
let session={running:false,seconds:0,baseSeconds:0,mode:'主动助力',intensity:30,minutes:20,checked:false,patientId:null,interval:null,startedAt:null,startedDate:null,runId:null};
let restored=false,storageHealthy=true,calendarMonth=today.slice(0,7),calendarDay=today,taskFilter='全部',calendarPatient='全部';
try{const draft=restoreSession(JSON.parse(localStorage.getItem(SESSION_KEY)),db.patients.map(x=>x.id));if(draft){session={...session,...draft};selected=draft.patientId;restored=true}}catch{}
const p=()=>db.patients.find(p=>p.id===selected)||db.patients[0];
const uid=prefix=>prefix+'-'+(globalThis.crypto?.randomUUID?.()||Array.from(globalThis.crypto?.getRandomValues?.(new Uint8Array(12))||Array.from({length:12},()=>Math.floor(Math.random()*256)),n=>n.toString(16).padStart(2,'0')).join('')).slice(0,12);
const when=()=>new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});
function save(action){try{if(action){db.audit.unshift({date:when(),action});db.audit=db.audit.slice(0,200)}db.settings.selectedPatient=selected||null;db.savedAt=when();localStorage.setItem(STORAGE_KEY,JSON.stringify(db));storageHealthy=true;return true}catch{storageHealthy=false;toast('本地保存未成功，请下载完整备份保留当前记录');return false}}
function toast(s){if(!storageHealthy&&/已保存|已恢复|已导入|已清空|已删除/.test(s))s='当前更改仅保留在页面内存，请下载备份保留记录';const n=document.createElement('div');n.className='toast';n.textContent=s;$('#toasts').append(n);setTimeout(()=>n.remove(),3600)}
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',patients:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',activity:'M2 12h5l3-8 4 16 3-8h5',wave:'M2 12h3l2-5 3 12 3-16 3 12 2-6 2 3h2',report:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h5',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z M20 2v4 M18 4h4',device:'M5 3h14a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2 M8 22h8 M12 18v4 M7 11h3l2-4 2 7 2-3h2',chart:'M3 3v18h18 M7 16v-5 M12 16V7 M17 16v-8',book:'M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1z M12 5v15',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3l-1 3-3 1-2 3 2 2-1 3 2 3 3-1 2 4h3l1-3 3-1 2-3-2-2 1-3-2-3-3 1-2-4z',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M13 6l6 6-6 6',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',upload:'M12 16V4 M7 9l5-5 5 5 M4 16v5h16v-5',check:'M5 12l4 4L19 6',shield:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6z M8 12l3 3 5-6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',play:'m8 4 12 8-12 8z',pause:'M8 4v16 M16 4v16',stop:'M5 5h14v14H5z',menu:'M4 6h16 M4 12h16 M4 18h16',chat:'M21 11a8 8 0 0 1-8 8H7l-5 3V11a9 9 0 0 1 19 0z',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8z',warning:'M12 3 2 21h20z M12 9v5 M12 17v1',link:'M10 13a5 5 0 0 0 7 0l4-4a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-4 4a5 5 0 0 0 7 7l2-2'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.spark}"/></svg>`;
const tag=(s,t='')=>`<span class="pill ${t}">${esc(s)}</span>`;
const btn=(label,act,cls='',ic='')=>`<button class="btn ${cls}" data-action="${act}">${ic?icon(ic):''}${label}</button>`;
const link=(label,dest)=>`<a class="link" href="#${dest}">${label}</a>`;
const badge=s=>tag(s,s==='待评估'||s==='待审核'||s==='待复核'?'amber':s==='居家训练'?'blue':'');
const head=(label,title,desc,actions='')=>`<div class="page-head"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p>${desc}</p></div><div class="head-actions">${actions}</div></div>`;
const card=(title,body,extra='',sub='')=>`<section class="card"><div class="card-head"><div><h2>${title}</h2>${sub?`<p class="card-sub">${sub}</p>`:''}</div>${extra}</div><div class="card-body">${body}</div></section>`;
const metric=(name,n,unit,foot,ic)=>`<div class="metric"><div class="metric-top">${name}<span class="metric-icon">${icon(ic)}</span></div><div class="metric-value">${n}<small>${unit}</small></div><div class="metric-foot">${foot}</div></div>`;
const avatar=x=>`<div class="avatar" style="background:${/^#[0-9a-f]{6}$/i.test(x.color)?x.color:'#edf5f0'}">${esc(x.name.slice(0,1))}</div>`;
const navs=[['overview','dashboard','康复工作台'],['patients','patients','患者管理'],['training','activity','训练中心'],['emg','wave','肌电分析'],['reports','report','康复报告'],['assistant','spark','智能辅助'],['devices','device','设备管理'],['analytics','chart','数据分析'],['followups','clock','随访计划']];
function hand(cls=''){return `<svg class="hand ${cls}" viewBox="0 0 220 220" fill="none" aria-label="手部康复示意"><g stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><path d="M76 181c-8-18-23-35-30-48-7-13 5-23 15-12l17 20V68c0-14 20-14 20 0v48-69c0-15 21-15 21 0v65-54c0-15 21-15 21 0v60-42c0-15 20-15 20 0v77c0 16-5 25-14 39v14H77z" stroke-width="2.5" fill="#d9eee3" fill-opacity=".75"/><path d="M97 70v48 M119 58v57 M140 76v44 M79 142c19-6 41-4 55 3 M96 157c-2 14 1 23 7 31 M133 152c3 10 3 21 0 34" stroke-width="1.3" opacity=".6"/><path d="M87 184 110 126l30 56 M110 126l-14-30 M110 126l9-41 M110 126l28-29 M110 126l42-8" stroke-width="1" stroke-dasharray="3 5" opacity=".65"/></g>${[[110,126],[96,96],[119,85],[138,97],[152,118],[87,184],[140,182]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4" fill="#effaf3" stroke="#6aa78e" stroke-width="1.5"/>`).join('')}<circle cx="110" cy="126" r="13" stroke="#72ad95" opacity=".35"/></svg>`}
function shell(content){const title=navs.find(x=>x[0]===view)?.[2]||({detail:'患者档案',home:'我的康复',knowledge:'康复课堂',about:'关于掌芯智护',settings:'数据与设置'}[view])||'康复工作台';return `<div class="layout"><aside class="sidebar" id="sidebar"><a href="#overview" class="brand"><div class="brand-symbol">${icon('activity')}</div><div><strong>芯护云</strong><small>ZHANGXIN CARE CLOUD</small></div></a><div class="space-label">康复管理 · WORKSPACE</div><nav class="nav">${navs.map(([id,ic,label])=>`<a href="#${id}" class="${view===id||view==='detail'&&id==='patients'?'active':''}">${icon(ic)}${label}</a>`).join('')}</nav><div class="space-label" style="padding-top:21px">服务与探索</div><nav class="nav">${[['home','heart','我的康复'],['knowledge','book','康复课堂'],['about','shield','关于掌芯智护']].map(([id,ic,label])=>`<a href="#${id}" class="${view===id?'active':''}">${icon(ic)}${label}</a>`).join('')}</nav><div class="sidebar-tail"><div class="support-card"><div class="row" style="gap:7px;color:#6c9b89">${icon('spark')}<h3>让康复，多一份陪伴</h3></div><p>康复知识、使用指引，随时查阅。</p><a class="link" href="#assistant" style="font-size:10px">与小芯聊聊 ${icon('arrow')}</a></div><a class="side-status row" href="#settings"><span class="dot teal"></span>公开体验版 · 本地独立档案 ${icon('settings')}</a></div></aside><main class="main"><header class="topbar"><div class="row"><button class="icon-button mobile-menu" data-action="menu" aria-label="展开导航">${icon('menu')}</button><div class="breadcrumb">工作空间 <span style="padding:0 10px;color:#cbd3d4">/</span> <b>${title}</b></div></div><div class="top-tools"><button class="top-search" data-action="global-search">${icon('search')}搜索患者、功能或康复知识 <span class="key">⌘ K</span></button><span class="pill"><span class="dot"></span>公众可访问</span><button class="icon-button" data-action="notifications" aria-label="通知">${icon('bell')}</button><button class="user" data-action="role"><div class="avatar">访</div><span class="user-label">访客体验<small>独立演示空间</small></span></button></div></header><div class="content">${content}<footer class="footer"><span>© ${new Date().getFullYear()} 芯护云 · 掌芯智护　 /　让每一次努力，都被看见</span><span>示例数据 · 非诊疗服务　 <button data-action="scope">功能与数据说明</button>　<a href="#settings">数据与隐私</a></span></footer></div></main><nav class="mobile-bottom" aria-label="手机快捷导航">${[['overview','dashboard','总览'],['patients','patients','档案'],['training','activity','训练'],['followups','clock','随访'],['home','heart','我的']].map(([id,ic,label])=>'<a href="#'+id+'" class="'+(view===id?'active':'')+'">'+icon(ic)+'<span>'+label+'</span></a>').join('')}</nav></div>`}
function patientSelect(id='patient-select'){return `<select id="${id}" aria-label="选择体验档案">${db.patients.map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.name)} · ${esc(x.id)}</option>`).join('')}</select>`}
const sessionsFor=id=>db.sessions.filter(s=>s.patientId===id);
const line=(name,val)=>`<div class="list-line"><span>${name}</span><strong style="font-weight:550">${val}</strong></div>`;
function patientTable(list=db.patients.slice(0,4)){return `<div class="table-scroll"><table><thead><tr><th>患者 / 编号</th><th>康复阶段</th><th>训练状态</th><th>计划进度</th><th>操作</th></tr></thead><tbody>${list.map(x=>`<tr><td><div class="patient-name">${avatar(x)}<div><strong>${esc(x.name)} <span class="muted small" style="font-weight:400;font-size:9px">${x.age}岁</span></strong><small>${esc(x.id)}</small></div></div></td><td>${esc(x.stage)}<div class="sub" style="font-size:9px">${esc(x.side)} · ${esc(x.location)}</div></td><td>${badge(x.status)}</td><td><div class="progress-line"><div class="bar"><i style="width:${x.progress}%"></i></div><span style="font-size:10px">${x.progress}%</span></div></td><td><button class="link" data-patient="${esc(x.id)}" style="font-size:10px">查看 →</button></td></tr>`).join('')}</tbody></table></div>`}
function overview(){const recent=db.sessions.filter(s=>s.date===today),total=db.sessions.length,person=p();return `${head('REHABILITATION WORKSPACE','康复工作台','欢迎来到芯护云，用数据连接每一段康复旅程。',btn('导出数据','export-sessions','','download')+btn('新建体验档案','new-patient','primary','plus'))}<section class="hero"><div class="hero-copy"><div class="hero-label">掌芯智护 · 全周期智能康复</div><h2>让每一次努力，都被看见。</h2><p>从院内评估到居家训练，让康复有迹可循，让照护始终在线。</p><div class="row"><a href="#training" class="btn primary">开始康复体验 ${icon('arrow')}</a><a href="#about" class="btn" style="background:#ffffff80;border-color:#ffffffa0">了解掌芯智护</a></div></div><div class="hero-art">${hand()}</div><div class="hero-chip"><span class="dot" style="color:#80ae96;margin-right:6px"></span>肌电感知 · 智能辅助 · 连续照护</div></section><div class="metrics">${metric('体验档案',db.patients.length,'人',`<b>${db.patients.filter(x=>x.location==='院内').length} 人</b> 院内 · ${db.patients.filter(x=>x.location!=='院内').length} 人社区 / 居家`,'patients')}${metric('今日训练记录',recent.length,'次',`累计 ${total} 次 · 含示例训练`,'activity')}${metric('平均计划进度',Math.round(db.patients.reduce((a,x)=>a+x.progress,0)/Math.max(1,db.patients.length)),'%',`阶段目标由体验档案记录`,'chart')}${metric('待处理事项',db.plans.filter(x=>x.status==='待审核').length+db.reports.filter(x=>x.status==='待审核').length+db.patients.filter(x=>x.status==='待评估').length,'项','方案审核 · 报告复核 · 阶段评估','report')}</div><div class="grid-main">${card('<span class="dot"></span>肌电信号监测',`<div class="chart-legend"><span><i class="dot" style="color:#6ca992"></i>屈肌通道</span><span><i class="dot" style="color:#97afd5"></i>伸肌通道</span><span class="grow"></span>${tag('模拟信号')}</div><div class="chart-container"><canvas id="signal-chart" aria-label="模拟肌电信号波形"></canvas></div><div class="chart-footer"><span>幅值 mV · ${esc(person?.name||'未选择档案')}</span><span>演示波形，不代表实时设备采集</span></div><div class="stats-strip"><div><small>屈肌 RMS · 示例</small><strong>0.0784 <span>mV</span></strong></div><div><small>伸肌 RMS · 示例</small><strong>0.0495 <span>mV</span></strong></div><div><small>信号来源</small><strong style="font-size:12px">内置模拟器</strong></div></div>`,`<div class="tabs"><button data-signal="stable" class="active">稳定波形</button><button data-signal="noisy">波动样例</button></div>`,'感知细微变化，关注每一步恢复')}${card('关注与提醒',`<div class="risk-item">${icon('warning')}<div><h3>设备巡检 · 信号波动样例</h3><p>ZX-004 为异常信号示例，可查看数据质量分析流程。</p><a class="link" href="#emg" style="font-size:10px">查看波形分析 →</a></div></div><div class="todo"><div class="todo-icon">${icon('report')}</div><div><h3>${db.plans.filter(x=>x.status==='待审核').length} 份方案待审核</h3><p>审核后进入体验训练计划</p></div>${link('查看 →','assistant')}</div><div class="todo"><div class="todo-icon" style="background:#f1f4fa;color:#8ca5ce">${icon('patients')}</div><div><h3>${db.patients.filter(x=>x.status==='待评估').length} 位体验患者待评估</h3><p>记录阶段性运动功能评分</p></div>${link('评估 →','patients')}</div><div class="todo"><div class="todo-icon" style="background:#f9f4e9;color:#bda779">${icon('home')}</div><div><h3>居家训练，持续陪伴</h3><p>查看任务和训练感受记录</p></div>${link('进入 →','home')}</div>`,tag('体验工作流','amber'))}</div><div class="grid-main">${card('最近患者',patientTable(),link('全部患者 →','patients'),'独立体验档案 · 点击查看康复详情')}${card('快捷工作入口',`<div class="quick-list">${[['assessment','report','量表记录','阶段性评估'],['new-report','report','生成报告','整理康复数据'],['new-plan','spark','方案草稿','保留人工审核'],['bind-device','device','绑定设备','管理体验设备']].map(([act,ic,t,s])=>`<button class="quick" data-action="${act}"><span class="todo-icon">${icon(ic)}</span><span><strong>${t}</strong><small>${s}</small></span></button>`).join('')}</div><div class="row between" style="margin-top:21px;padding-top:15px;border-top:1px solid var(--line)"><span style="font-size:10px;color:#95a9a3">从了解开始，让康复更从容</span>${link('康复课堂 →','knowledge')}</div>`)}</div>`}
function patientsPage(){const list=db.patients.filter(x=>(filter==='全部'||x.status===filter)&&`${x.name}${x.id}${x.diagnosis}`.toLowerCase().includes(search.toLowerCase()));return `${head('PATIENT MANAGEMENT','患者管理','为每一份康复努力，建立连续、清晰的记录。',btn('导出档案','export-patients','','download')+btn('新建体验档案','new-patient','primary','plus'))}<div class="search-row"><label class="screen-reader" for="patient-search">搜索患者</label><input id="patient-search" class="input" placeholder="搜索姓名、编号或诊断" value="${esc(search)}"><select id="patient-filter" aria-label="按训练状态筛选">${['全部','训练中','居家训练','待评估','待复核'].map(x=>`<option ${filter===x?'selected':''}>${x}</option>`).join('')}</select><span class="grow"></span><span class="muted small">共 ${list.length} 份体验档案</span></div><div class="patient-grid">${list.map(x=>`<article class="patient-card"><div class="row">${avatar(x)}<div><h3>${esc(x.name)} <small class="muted" style="font-size:10px;font-weight:400">${x.age}岁 · ${esc(x.sex)}</small></h3><div class="sub" style="font-size:10px">${esc(x.id)}</div></div><div class="grow"></div>${badge(x.status)}</div><div class="sub" style="margin-top:15px">${esc(x.diagnosis)} · ${esc(x.side)}</div><dl class="facts"><div><dt>康复阶段</dt><dd>${esc(x.stage)}</dd></div><div><dt>FMA 上肢总分</dt><dd>${x.score} / 66 <span class="teal" style="font-size:10px">↑ ${x.score-x.baseline}</span></dd></div><div><dt>累计训练</dt><dd>${sessionsFor(x.id).length} 次</dd></div><div><dt>康复场景</dt><dd>${esc(x.location)}</dd></div></dl><div class="bar"><i style="width:${x.progress}%"></i></div><div class="row between" style="margin-top:10px"><span class="muted" style="font-size:10px">阶段计划进度 ${x.progress}%</span><button class="link" data-patient="${esc(x.id)}">查看档案 →</button></div></article>`).join('')||'<div class="empty card" style="grid-column:1/-1">没有找到匹配的体验档案。可调整关键词或新建档案。</div>'}</div>`}
function historyTable(id){const list=sessionsFor(id).slice().reverse();return `<div class="table-scroll"><table><thead><tr><th>日期</th><th>训练模式</th><th>实际时长</th><th>完成度</th><th>训练感受 / 来源</th></tr></thead><tbody>${list.slice(0,30).map(s=>`<tr><td>${esc(s.date)}</td><td>${esc(s.mode)}</td><td>${Math.floor(s.seconds/60)}分${s.seconds%60}秒</td><td>${s.completion}%</td><td>${esc(s.feeling)}<small class="muted" style="display:block;font-size:9px">${esc(s.source)}</small></td></tr>`).join('')||'<tr><td colspan="5" class="empty">尚无训练记录</td></tr>'}</tbody></table></div>`}
function detailPage(){const x=p();if(!x)return '<div class="empty">请先新建体验档案</div>';let body;if(detailTab==='history')body=historyTable(x.id);else if(detailTab==='assessment')body=`${db.assessments.filter(a=>a.patientId===x.id).slice().reverse().map(a=>line(`${esc(a.date)} · ${esc(a.assessor)}`,`${a.score} / 66 分`)).join('')||'<p class="empty">尚无量表记录</p>'}${btn('录入新评估','assessment','soft','plus')}<p class="note">仅记录由受训评估人员完成的 FMA 上肢运动功能总分，不用软件代替量表实施。</p>`;else if(detailTab==='notes')body=`<div class="timeline">${db.notes.filter(n=>n.patientId===x.id).slice().reverse().map(n=>`<div class="timeline-item"><h3>${esc(n.date)}</h3><p>${esc(n.text)}</p></div>`).join('')||'<p class="muted small">暂未添加备注。</p>'}</div><form id="note-form"><label class="field"><span>病程与照护备注</span><textarea name="text" maxlength="2000" required placeholder="填写训练观察、患者感受或后续关注事项"></textarea></label><button class="btn soft" type="submit">保存备注</button></form>`;else body=`<div class="result-grid"><div><small>阶段计划进度</small><b>${x.progress}%</b></div><div><small>FMA 上肢</small><b>${x.score}<small>/ 66 分</small></b></div><div><small>累计训练</small><b>${sessionsFor(x.id).length}<small>次 · 含示例</small></b></div></div><div class="chart-container"><canvas id="progress-chart"></canvas></div><p class="note">趋势依据当前档案中的评估记录绘制；仅有一个评估点时不推测历史数值。</p>`;return `${head('PATIENT PROFILE','患者档案','患者管理 / 连续康复记录',`<a class="btn" href="#patients">返回列表</a>`+btn('编辑档案','edit-patient','','patients')+`<a class="btn primary" href="#training">进入训练 ${icon('arrow')}</a>`)}<section class="card"><div class="detail-summary">${avatar(x)}<div><h2 style="font-size:21px">${esc(x.name)}</h2><p class="sub">${esc(x.id)} · ${x.age}岁 · ${esc(x.sex)} · ${esc(x.diagnosis)}</p></div><span class="grow"></span>${badge(x.status)}</div><div class="kv-grid"><div><small>康复阶段</small><strong>${esc(x.stage)} · ${esc(x.side)}</strong></div><div><small>康复场景</small><strong>${esc(x.location)}</strong></div><div><small>绑定设备</small><strong>${esc(x.device)||'未绑定'}</strong></div><div><small>较基线评分变化</small><strong class="teal">${x.score-x.baseline>=0?'+':''}${x.score-x.baseline} 分</strong></div></div></section><div class="section-tabs">${[['overview','康复概览'],['history','训练记录'],['assessment','量表评估'],['notes','病程备注']].map(([id,t])=>`<button data-tab="${id}" class="${detailTab===id?'active':''}">${t}</button>`).join('')}</div><div class="grid-main">${card({overview:'康复进度',history:'训练记录',assessment:'量表评估记录',notes:'病程与照护记录'}[detailTab],body,btn('生成报告','new-report','tiny'))}<div class="stack">${card('当前训练计划',planSummary(x.id))}${card('档案数据管理',`<p class="result-text">当前体验记录保存在本浏览器。导出备份可用于迁移和留存。</p><div class="row mt">${btn('导出此档案','export-profile','','download')}${btn('删除档案','delete-patient','danger')}</div>`)}</div></div>`}
function planSummary(id){const plan=db.plans.filter(x=>x.patientId===id&&x.status==='已确认').at(-1);return plan?`${line('训练模式',esc(plan.mode))}${line('目标时长',plan.minutes+' 分钟')}${line('体验强度',plan.intensity+'%')}${line('确认人',esc(plan.reviewer||'体验审核'))}<p class="note">仅应用于体验工作流，不向真实设备下发参数。</p>`:`<div class="notice-empty">尚无已确认的训练方案</div>${btn('生成方案草稿','new-plan','soft','spark')}<p class="note">草稿经体验审核后可加载到训练中心。</p>`}
function trainingPage(){const x=p();if(!x)return '<div class="empty">请先创建档案。</div>';const count=sessionsFor(x.id).filter(s=>s.date===today).length;return `${head('TRAINING CENTER','训练中心','把训练过程变成清晰记录，关注每一次真实感受。',patientSelect())}<div class="info-banner">当前为模拟训练：计时、记录与反馈可以使用；页面不会驱动真实康复手套。参数仅供体验。</div><div class="training-grid"><div class="stack">${card('训练配置',`<div class="mode-grid">${['被动训练','主动助力','阻力训练'].map((m,i)=>`<button class="mode ${session.mode===m?'active':''}" data-mode="${m}" ${session.running?'disabled':''}>${icon(['heart','activity','shield'][i])}${m}</button>`).join('')}</div><div class="mt"><label class="field"><span>目标时长</span><select id="duration" ${session.running?'disabled':''}>${[...new Set([1,5,10,15,20,30,45,60,session.minutes])].sort((a,b)=>a-b).map(n=>`<option value="${n}" ${n===session.minutes?'selected':''}>${n} 分钟${n===1?' · 快速体验':''}</option>`).join('')}</select></label><label class="field"><span class="row between">体验强度 <b id="intensity-label">${session.intensity}%</b></span><input id="intensity" type="range" min="5" max="60" value="${session.intensity}" ${session.running?'disabled':''}><small>界面参数，不代表硬件输出或医疗建议</small></label><label class="checkline"><input type="checkbox" id="training-check" ${session.checked?'checked':''} ${session.running?'disabled':''}><span>我已了解这是模拟体验；实际训练应按专业人员制定的计划执行。</span></label>${btn('加载已确认方案','load-plan','soft','report')}</div>`)}${card('今日训练',`${line('已记录训练',count+' 次')}${line('当前体验对象',esc(x.name))}<p class="note">完成或结束后填写感受，记录将同步到本浏览器的患者档案和报告。</p>`)}</div><div class="stack">${card('手部训练空间',`<div class="training-stage"><div class="stage-label">HAND REHABILITATION · 模拟训练</div>${hand(session.running?'moving':'')}<div class="timer" id="timer">${formatTime(session.seconds)}</div><span class="muted" style="font-size:10px" id="session-status">${session.running?'正在计时':session.seconds?'已暂停':'准备开始'} · ${esc(session.mode)}</span></div><div class="session-tools">${btn(session.running?'暂停训练':session.seconds?'继续训练':'开始训练','toggle-training','primary',session.running?'pause':'play')}${btn('结束并记录','finish-training','','stop')}${btn('重置','reset-training')}</div><div class="bar mt"><i id="session-bar" style="width:${Math.min(100,session.seconds/(session.minutes*60)*100)}%"></i></div><div class="chart-footer"><span>目标 ${session.minutes} 分钟</span><span id="session-progress">${Math.min(100,Math.round(session.seconds/(session.minutes*60)*100))}%</span></div>`,tag(session.running?'计时中':'未运行',session.running?'':'gray'))}${card('节奏互动练习',`<div class="game"><div class="row between"><span class="small muted">点击目标，体验动作与反馈的连接</span><span class="pill">已完成 <b id="game-count">${gameHits}</b> 次</span></div><button class="game-target" data-action="game-hit" aria-label="点击互动训练目标">✧</button><p class="note">鼠标 / 触屏互动演示，无肌电动作识别或临床评定功能。</p></div>`)}</div></div>`}
function emgPage(){return `${head('EMG SIGNAL ANALYSIS','肌电分析','导入采样数据，观察波形、特征与信号质量。',btn('下载 CSV 模板','sample-csv','','download')+btn('载入示例信号','sample-emg','primary','wave'))}<div class="grid-main"><div class="stack">${card('数据采集与导入',`<div class="analysis-upload">${icon('upload')}<h3>导入肌电采样 CSV 文件</h3><p>time_ms, flexor_mv, extensor_mv · 最大 5 MB / 50,000 行<br>时间严格递增，通道幅值单位为 mV。</p><label class="btn primary" for="emg-file">选择 CSV 文件</label><input type="file" id="emg-file" accept=".csv,text/csv" hidden></div><p class="note">文件仅在当前浏览器内解析，不上传服务器。请使用去标识化的采样数据。</p>`)}${card('波形与计算结果',emg?`<div class="row between mb"><span class="small muted">${esc(emg.name)}</span>${tag(emg.source==='sample'?'模拟样例':'导入采样','blue')}</div><div class="chart-legend"><span><i class="dot" style="color:#6ca992"></i>屈肌通道 mV</span><span><i class="dot" style="color:#9bafd4"></i>伸肌通道 mV</span></div><div class="chart-container" style="height:230px"><canvas id="emg-chart"></canvas></div><div class="result-grid"><div><small>屈肌 RMS</small><b>${emg.stats.flex.rms.toFixed(4)}</b><small>mV</small></div><div><small>伸肌 RMS</small><b>${emg.stats.ext.rms.toFixed(4)}</b><small>mV</small></div><div><small>峰峰值 · 屈肌</small><b>${emg.stats.flex.p2p.toFixed(4)}</b><small>mV</small></div></div>${line('样本点数',emg.rows.length+' 点')}${line('时长',((emg.rows.at(-1)[0]-emg.rows[0][0])/1000).toFixed(3)+' 秒')}${line('估计采样率',(emg.stats.rate).toFixed(1)+' Hz')}${line('采样间隔最大偏离',emg.stats.jitter.toFixed(1)+'%')}${line('屈肌平均绝对值',emg.stats.flex.mav.toFixed(4)+' mV')}${line('屈肌过零率',emg.stats.flex.zcr.toFixed(4))}${btn('导出特征结果','export-emg','soft','download')}`:'<div class="empty">载入示例，或导入 CSV 后查看波形与特征计算。</div>')}</div><div class="stack">${card('信号质量提示',emg?`<div class="timeline">${emg.stats.warnings.map(w=>`<div class="timeline-item"><h3>${esc(w.title)}</h3><p>${esc(w.text)}</p></div>`).join('')}</div><p class="note">采用透明的启发式规则：平直信号、孤立跳变、极值重复与采样不均。未接入项目时序 AI 模型，不用于医学异常识别。</p>`:`<div class="notice-empty">分析数据后显示检查结果</div>`,tag('规则分析','amber'))}${card('三层分析路径',`<div class="timeline"><div class="timeline-item"><h3>01 · 波形与质量</h3><p>先查看采样是否完整、时间是否递增、信号是否平直。</p></div><div class="timeline-item"><h3>02 · 特征计算</h3><p>RMS、平均绝对值、峰峰值与过零率，均由所选采样实际计算。</p></div><div class="timeline-item"><h3>03 · 专业判断</h3><p>肌力、疲劳、震颤及康复方案需要标准化采集与经验证的模型及专业人员判断。</p></div></div><a class="link" href="#assistant">生成体验方案草稿 →</a>`)}${card('真实设备接入',`<p class="result-text">附件未提供硬件通信协议、设备网关或模型服务。本版提供 CSV 数据入口和协议说明。</p><div class="mt">${btn('查看接入要求','integration','soft','link')}</div>`)}</div></div>`}
function reportsPage(){return `${head('REHABILITATION REPORTS','康复报告','把训练、评估和观察，整理成可复核的记录。',patientSelect()+btn('生成报告','new-report','primary','plus'))}<div class="info-banner">报告按当前体验档案汇总实际已保存记录，可下载文本或通过浏览器打印为 PDF。审核仅用于演示工作流。</div>${card('报告归档',`<div class="table-scroll"><table><thead><tr><th>报告编号</th><th>患者</th><th>生成时间</th><th>状态</th><th>操作</th></tr></thead><tbody>${db.reports.slice().reverse().map(r=>`<tr><td>${esc(r.id)}</td><td>${esc(db.patients.find(x=>x.id===r.patientId)?.name||'已删除档案')}</td><td>${esc(r.date)}</td><td>${badge(r.status)}</td><td><button class="link" data-report="${esc(r.id)}">查看 / 下载 →</button></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">还没有报告。选择档案后，点击“生成报告”即可整理现有记录。</div></td></tr>'}</tbody></table></div>`)}<div class="grid-half mt">${card('报告包含什么',`${line('训练执行','模式、时长、完成度与感受')}${line('量表记录','人工录入的 FMA 上肢总分')}${line('方案与审核','草稿、确认信息与审核状态')}${line('病程与观察','当前档案的照护备注')}`)}${card('当前档案摘要',p()?`${line('体验患者',esc(p().name))}${line('累计训练',sessionsFor(selected).length+' 次')}${line('当前 FMA 总分',p().score+' / 66')}${line('记录范围','当前浏览器中的体验数据')}`:'<p class="empty">尚无档案</p>')}</div>`}
function assistantPage(){const drafts=db.plans.filter(x=>x.patientId===selected).slice().reverse();return `${head('INTELLIGENT ASSISTANCE','智能辅助','让数据整理更高效，让每一份方案保留专业判断。',patientSelect()+btn('生成方案草稿','new-plan','primary','spark'))}<div class="info-banner">小芯使用内置知识条目检索；方案按档案信息和透明规则整理。当前未接入大模型，不能提供诊断或个体化医疗建议。</div><div class="grid-main"><div class="stack">${card('小芯 · 康复知识助手',`<div class="chat"><div class="chat-log" id="chat-log"><div class="bubble">您好，我是小芯。可以帮您查找设备指引、康复知识和当前档案摘要。\n\n当前为${assistantRole}，回答来自内置条目检索。涉及诊疗和真实训练参数，请咨询专业人员。</div>${chat.map(m=>`<div class="bubble ${m.self?'self':''}">${esc(m.text)}</div>`).join('')}</div><form class="chat-form" id="chat-form"><input class="input" name="question" maxlength="1000" required placeholder="问问训练记录、设备指引或评估知识…" aria-label="向康复知识助手提问"><button class="btn primary" type="submit" aria-label="发送问题">${icon('arrow')}</button></form></div>`,`<div class="tabs">${['医护助手','患者助手'].map(x=>`<button data-assistant-role="${x}" class="${assistantRole===x?'active':''}">${x}</button>`).join('')}</div>`)}${card('方案草稿与审核',drafts.map(d=>`<div style="border-bottom:1px solid var(--line);padding-bottom:20px;margin-bottom:20px"><div class="row between"><h3 style="font-size:12px">${esc(d.id)} · ${esc(d.mode)}</h3>${badge(d.status)}</div><p class="note">${esc(d.date)} · 目标 ${d.minutes} 分钟 · 体验强度 ${d.intensity}%</p><p class="result-text" style="margin:10px 0">${esc(d.reason)}</p>${d.status==='待审核'?`<div class="row">${btn('查看并审核','review-plan:'+d.id,'soft','check')}${btn('编辑草稿','edit-plan:'+d.id,'tiny')}</div>`:`<p class="note">${esc(d.reviewer||'')} · ${esc(d.reviewNote||'')}<br>仅体验确认，未向真实设备下发。</p>`}</div>`).join('')||'<div class="empty">尚未生成草稿。点击右上角开始整理。</div>')}</div><div class="stack">${card('试着问问',`<div>${['生成当前档案摘要','如何佩戴电极和手套？','训练出现不适怎么办？','FMA 评分如何记录？','如何清洁设备？','居家训练如何记录？'].map(q=>`<button class="question-chip" data-question="${q}">${q} <span style="float:right;color:#afc0b7">↗</span></button>`).join('')}</div>`)}${card('需要人工确认的闭环',`<div class="timeline"><div class="timeline-item"><h3>整理已有信息</h3><p>档案、量表和训练记录；规则结果可查看依据。</p></div><div class="timeline-item"><h3>生成体验草稿</h3><p>保留可编辑的模式、时长、说明，不自动生效。</p></div><div class="timeline-item"><h3>人工审核确认</h3><p>填写审核人与意见后，可加载到模拟训练。</p></div></div>`)}${card('项目 AI 能力接入',`<p class="result-text">项目提出时序模型异常识别、个性化方案与 AI 小助手三项能力。当前公开版落实交互和审核流程，模型推理需要接入真实服务。</p><div class="mt">${btn('查看能力说明','scope','soft')}</div>`)}</div></div>`}
function devicesPage(){return `${head('DEVICE MANAGEMENT','设备管理','让设备、使用记录和维护事项保持清晰。',btn('新增 / 绑定设备','bind-device','primary','plus'))}<div class="info-banner">设备卡片为本地体验资产，在线状态、电量为示例值。绑定和维护记录会保存；未建立真实硬件连接。</div><div class="device-grid">${db.devices.map(d=>`<article class="device-card"><div class="row between"><h3>${esc(d.id)}</h3>${tag(d.status,d.status==='需巡检'?'amber':'')}</div><div class="device-art">${icon('device')}</div><h3>${esc(d.name)}</h3><p class="sub">${esc(d.firmware)} · 示例设备</p>${line('绑定患者',esc(db.patients.find(x=>x.id===d.patientId)?.name||'未绑定'))}${line('电量 · 示例',d.battery+'%')}${line('维护记录',d.maintenance.length+' 条')}<div class="row mt">${btn('查看 / 维护','device:'+d.id,'tiny','settings')}${btn('重新绑定','rebind:'+d.id,'tiny')}</div></article>`).join('')}</div><div class="grid-half mt">${card('设备使用流程',`<div class="timeline"><div class="timeline-item"><h3>建立资产记录</h3><p>录入设备编号，关联体验档案。</p></div><div class="timeline-item"><h3>维护与巡检</h3><p>记录问题、操作与处理结果，可追溯修改时间。</p></div><div class="timeline-item"><h3>导入采样分析</h3><p>按 CSV 模板导入采集数据，查看波形与特征。</p></div></div>`)}${card('硬件接入准备',`<p class="result-text">后续接入需要厂商确认的协议、采样格式、设备鉴权和安全停机机制。公开版不会生成未知硬件控制指令。</p><div class="row mt"><a class="btn soft" href="#emg">导入采样数据</a>${btn('查看接口约定','integration','','link')}</div>`)}</div>`}
function analyticsPage(){const since=localDate(new Date(Date.now()-(range-1)*86400000)),data=db.sessions.filter(s=>s.date>=since),count=data.length,avg=Math.round(data.reduce((a,s)=>a+s.completion,0)/Math.max(1,count)),mins=(data.reduce((a,s)=>a+s.seconds,0)/Math.max(1,count)/60).toFixed(1),modes=['主动助力','被动训练','阻力训练'];return `${head('REHABILITATION INSIGHTS','数据分析','依据当前体验记录，观察服务过程与训练执行。',`<select id="analytics-range" aria-label="统计时间范围">${[7,14,30].map(n=>`<option value="${n}" ${range===n?'selected':''}>近 ${n} 天</option>`).join('')}</select>`+btn('导出统计','export-analytics','','download'))}<div class="metrics">${metric('训练记录',count,'次',since+' 至 '+today,'activity')}${metric('平均完成度',avg,'%',count?'依据所选范围内记录':'暂无训练数据','check')}${metric('平均训练时长',mins,'分钟','以实际记录时长计算','clock')}${metric('覆盖体验档案',new Set(data.map(s=>s.patientId)).size,'人','含内置示例记录','patients')}</div><div class="grid-main">${card('训练量趋势',`<div class="chart-container" style="height:260px"><canvas id="analytics-chart"></canvas></div><p class="note">按中国标准时间归档日期统计。示例训练与新完成的体验记录同时纳入。</p>`,tag(`近 ${range} 天`))}${card('训练模式分布',`<div class="donut" id="mode-donut"><span>${count}<small>训练记录总量</small></span></div>${modes.map((m,i)=>`<div class="row between" style="font-size:11px;margin-top:12px"><span><i class="dot" style="background:${['#75b69b','#92afd7','#d1b98a'][i]};margin-right:7px"></i>${m}</span><span class="muted">${data.filter(s=>s.mode===m).length} 次 · ${count?Math.round(data.filter(s=>s.mode===m).length/count*100):0}%</span></div>`).join('')}`)}</div>${card('康复阶段与训练执行',`<div class="table-scroll"><table><thead><tr><th>阶段</th><th>档案数</th><th>范围内训练</th><th>平均完成度</th><th>待评估档案</th></tr></thead><tbody>${['早期','恢复期','巩固期'].map(stage=>{const people=db.patients.filter(x=>x.stage===stage),s=data.filter(s=>people.some(x=>x.id===s.patientId));return `<tr><td>${stage}</td><td>${people.length}</td><td>${s.length} 次</td><td>${s.length?Math.round(s.reduce((a,x)=>a+x.completion,0)/s.length)+'%':'—'}</td><td>${people.filter(x=>x.status==='待评估').length}</td></tr>`}).join('')}</tbody></table></div><p class="note">过程指标不等同于临床疗效。平台不据此输出疗效排名或康复预测。</p>`)}`}
function homePage(){const x=p();if(!x)return '<div class="empty">请先创建体验档案</div>';const todaySessions=sessionsFor(x.id).filter(s=>s.date===today),tasks=[['prepare','训练前设备与皮肤检查','按说明书和专业人员指导确认'],['record','完成今日体验训练','记录实际时长和感受'],['feedback','整理训练感受','有异常时及时联系康复师']],key=today+'-'+x.id;return `${head('MY REHABILITATION','我的康复','把康复融入日常，每一步都值得被记录。',patientSelect())}<div class="hero"><div class="hero-copy"><div class="hero-label">${esc(x.name)}，今天也向前一步</div><h2>慢慢来，进步正在发生。</h2><p>按计划训练，如实记录感受，让照护团队更了解您的状态。</p><a class="btn primary" href="#training">开始今日体验 ${icon('arrow')}</a></div><div class="hero-art">${hand()}</div><div class="hero-chip">今日已记录 ${todaySessions.length} 次训练</div></div><div class="grid-half">${card('今日小目标',`<div>${tasks.map(([id,title,sub])=>`<label class="care-task"><input type="checkbox" data-care="${id}" ${db.checks[key+'-'+id]?'checked':''}><span><strong>${title}</strong><small>${sub}</small></span></label>`).join('')}</div><p class="note">此清单由您自行勾选，反映体验任务状态，不代表治疗完成。</p>`)}${card('我的康复记录',`${line('阶段计划进度',x.progress+'%')}${line('最近 FMA 记录',x.score+' / 66 分')}${line('今日记录训练',todaySessions.length+' 次')}<div class="row mt">${btn('查看我的报告','new-report','soft','report')}${btn('记录今日感受','feedback','','heart')}</div>`)}</div><div class="grid-half mt">${card('随访与提醒',`<form id="task-form"><div class="form-grid"><label class="field full"><span>提醒内容</span><input class="input" name="title" maxlength="100" required placeholder="例如：复诊时携带训练记录"></label><label class="field"><span>日期</span><input class="input" type="date" name="date" value="${today}" required></label><label class="field"><span>时间</span><input class="input" type="time" name="time" value="${esc(db.settings.remind)}" required></label></div><button class="btn soft" type="submit">${icon('plus')}添加本地提醒</button></form><div class="mt">${db.tasks.filter(t=>t.patientId===selected).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(t=>`<div class="care-task"><input type="checkbox" data-task="${esc(t.id)}" ${t.done?'checked':''} aria-label="完成提醒"><span><strong>${esc(t.title)}</strong><small>${esc(t.date)} ${esc(t.time)}</small></span></div>`).join('')||'<p class="note">尚无提醒。提醒在页面打开时检查，不发送短信或离线推送。</p>'}</div>`)}${card('照护沟通记录',`<div style="max-height:180px;overflow:auto">${db.messages.filter(m=>m.patientId===selected).slice(-8).map(m=>`<div class="timeline-item"><h3>${esc(m.from)} · ${esc(m.date)}</h3><p>${esc(m.text)}</p></div>`).join('')||'<p class="note">记录希望在复诊时沟通的事项，或体验照护留言。</p>'}</div><form id="message-form" class="mt"><label class="field"><span>留言 / 待沟通事项（仅保存在此浏览器）</span><textarea name="text" maxlength="1500" required placeholder="记录希望沟通的训练情况…"></textarea></label><button class="btn soft" type="submit">保存沟通记录</button></form><p class="note">本页不是在线问诊，留言不会发送给真实医生。</p>`)}</div><div class="mt">${card('康复小课堂',`<div class="quick-list">${articles.slice(0,4).map(a=>`<button class="quick" data-article="${a.id}"><span class="todo-icon">${icon(a.icon)}</span><span><strong>${a.title}</strong><small>${a.category}</small></span></button>`).join('')}</div>`,link('全部课程 →','knowledge'))}</div>`}
function knowledgePage(){const list=articles.filter(a=>`${a.title}${a.description}${a.category}`.includes(search));return `${head('REHABILITATION LIBRARY','康复课堂','理解训练、设备与记录，让照护更从容。')}<div class="search-row"><input class="input" id="knowledge-search" placeholder="搜索设备、评估、居家照护…" value="${esc(search)}" aria-label="搜索康复知识"><span class="muted small">${list.length} 篇精选指引</span></div><div class="article-grid">${list.map(a=>`<button class="article-card" data-article="${a.id}"><div class="article-art" style="background:${a.category==='设备指引'?'#eff3f8':a.category==='评估知识'?'#f4f1f8':'#edf6f0'}">${icon(a.icon)}</div>${tag(a.category)}<h3>${a.title}</h3><p>${a.description}</p><div class="link" style="margin-top:17px;font-size:11px">阅读指引 →</div></button>`).join('')||'<div class="empty">未找到匹配内容。</div>'}</div><p class="note">内容是平台使用与一般康复知识介绍，实际使用和训练以专业人员指导及设备说明书为准。</p>`}
function aboutPage(){return `${head('ABOUT ZHANGXIN','关于掌芯智护','AI 肌电驱动的人手全周期智能康复解决方案。',`<a class="btn primary" href="#training">体验平台 ${icon('arrow')}</a>`)}<div class="about-hero"><div class="eyebrow">感知 · 解析 · 辅助决策 · 训练 · 反馈</div><h1>从一束肌电信号开始，<br>连接一段完整的康复旅程。</h1><p>掌芯智护聚焦手功能康复，将肌电感知、康复手套与芯护云平台连接，面向医院、社区康复中心及家庭构建连续的训练与照护体验。</p></div><div class="mt">${card('一个平台，连接三个康复场景',`<div class="grid-half about-scenarios">${[['院内康复','patients','集中评估、训练配置、设备管理与报告复核。'],['社区接续','home','阶段记录、设备维护和训练过程跟踪。'],['居家巩固','heart','日常任务、感受反馈、康复课堂与随访记录。']].map(([t,i,d])=>`<div class="flow" style="display:block;background:#f8fbf9;padding:23px;border-radius:12px">${icon(i)}<h3 style="margin:13px 0 8px;color:#638d7b">${t}</h3><p style="font-size:11px;color:#98afa4">${d}</p></div>`).join('')}</div>`)}</div><div class="mt">${card('感知到反馈，构成连续的工作流',`<div class="flow">${[['01','感知','采集与导入肌电数据'],['02','解析','波形展示与特征计算'],['03','辅助决策','整理方案草稿并审核'],['04','训练','记录过程与完成情况'],['05','反馈','报告、感受与阶段复评']].map(([n,t,d])=>`<div><b>${n}</b><h3>${t}</h3><p>${d}</p></div>`).join('')}</div>`)}</div><div class="mt">${card('来自项目的真实原型',`<div class="hardware"><img src="./assets/emg-prototype.jpg" alt="项目材料中的肌电采集器、单片机与屏幕原型照片" loading="lazy"><div><div class="eyebrow">PROJECT PROTOTYPE</div><h2>以肌电感知，连接人手与数据。</h2><p>项目材料展示了肌电采集器、单片机和显示组件原型，并提出肌电感知与康复手套融合的技术路线。芯护云承载数据管理、训练过程记录、报告和智能辅助交互。</p><p>依据所提供的 2026 年项目材料，硬件融合调试和 AI 能力仍处于验证与完善阶段。网站以材料中的能力目标建立体验流程，不将规划功能表述为已通过临床验证。</p><span class="data-label">图片来源：用户提供的项目计划书</span></div></div>`)}</div><div class="grid-half mt">${card('三项智能辅助方向',`${line('肌电异常识别','信号质量 → 模型验证 → 人工判断')}${line('个性化方案草稿','数据整理 → 草稿 → 人工确认')}${line('平台小助手','知识查询 → 记录摘要 → 使用指引')}<p class="note">当前版采用透明规则和内置知识检索；真实项目模型服务尚未接入。</p>`)}${card('公开体验的功能边界',`<p class="result-text">公众无需注册即可查阅平台和体验全部页面。档案、报告、训练与提醒保存在当前浏览器，各访客之间不共享。</p><p class="result-text" style="margin-top:12px">要用于真实临床服务，还需接入身份权限、机构数据库、设备协议与经验证的 AI 服务。</p><div class="row mt">${btn('查看功能状态','scope','soft')}${btn('硬件与模型接入','integration')}</div>`)}</div>`}
function settingsPage(){return `${head('DATA & PREFERENCES','数据与设置','管理您的独立体验空间、备份与阅读偏好。')}<div class="settings-grid">${card('数据备份与迁移',`<p class="result-text">体验数据保存在此浏览器的本地存储中。清理浏览器、换设备或使用无痕模式可能导致数据丢失，请及时导出备份。</p><div class="row mt">${btn('下载完整备份','backup','primary','download')}<label class="btn" for="backup-file">${icon('upload')}导入备份</label><input type="file" id="backup-file" accept=".json,application/json" hidden></div><p class="note">导入前会验证结构，并要求确认替换。建议仅使用此平台导出的备份文件。</p>`)}${card('数据恢复与离线使用',`<p class="result-text">导入、删除档案或恢复示例之前，自动保留一份本地恢复点。换浏览器前请下载完整备份。</p><div class="row mt">${btn('查看恢复点','recovery','soft','clock')}${btn('使用导览','guide','','book')}</div><p class="note">最近发起备份：${esc(db.settings.lastBackupAt||'尚未下载')}<br>本次数据保存：${esc(db.savedAt||'示例数据，尚未修改')}</p>${location.protocol==='file:'?'<p class="note">当前正在使用离线单文件版。</p>':'<a class="btn mt" href="./downloads/xinhuyun-offline.html" download="芯护云-离线双击打开.html">下载完整离线版</a>'}`)}${card('使用偏好',`<label class="checkline"><input type="checkbox" id="large-text" ${db.settings.large?'checked':''}>舒适阅读：增加内容字号</label><label class="field mt"><span>默认提醒时间</span><input class="input" type="time" id="reminder-time" value="${esc(db.settings.remind)}"></label><p class="note">偏好自动保存。提醒仅在网页打开时检查，不发送短信或后台通知。</p>`)}${card('体验数据概况',`${line('体验档案',db.patients.length+' 份')}${line('训练记录',db.sessions.length+' 条')}${line('量表记录',db.assessments.length+' 条')}${line('报告归档',db.reports.length+' 份')}${line('本地存储占用',(new Blob([JSON.stringify(db)]).size/1024).toFixed(1)+' KB')}`)}${card('隐私与环境',`<p class="result-text">页面公众可访问；每位访客的档案留在各自浏览器。公开版没有真实用户账户、远程医患通道、医院系统同步或硬件控制。切换视图只改变体验界面。</p><p class="result-text mt">采样 CSV 在浏览器内计算，不上传文件。不建议在公开体验环境录入真实身份信息和敏感医疗数据。</p><div class="row mt">${btn('恢复初始示例','reset-data','danger')}${btn('清空全部本地数据','clear-data','danger')}</div>`)}</div><div class="mt">${card('最近操作记录',`<div class="timeline">${db.audit.slice(0,12).map(a=>`<div class="timeline-item"><h3>${esc(a.action)}</h3><p>${esc(a.date)}</p></div>`).join('')||'<div class="notice-empty">新建、训练、审核等操作会在这里记录。</div>'}</div>`)}</div>`}
const pages={overview,patients:patientsPage,detail:detailPage,training:trainingPage,emg:emgPage,reports:reportsPage,assistant:assistantPage,devices:devicesPage,analytics:analyticsPage,home:homePage,knowledge:knowledgePage,about:aboutPage,settings:settingsPage,followups:followupsPage};
function render(){refreshDay();document.body.classList.toggle('comfortable',!!db.settings.large);document.body.style.fontSize=db.settings.large?'16px':'';let content=(pages[view]||overview)();if(view==='overview')content=content.replace('<div class="metrics">',onboarding()+'<div class="metrics">');if(session.seconds)content='<div class="session-notice"><span>'+icon('clock')+(restored?'已找回上次训练 · ':'未归档训练 · ')+esc(db.patients.find(x=>x.id===session.patientId)?.name||'体验档案')+' · <b id="pending-time">'+formatTime(session.seconds)+'</b>'+(session.running?' · 计时中':' · 已暂停')+'</span><a href="#training">'+(view==='training'?'保存在本浏览器':'返回训练')+' →</a></div>'+content;if(!storageHealthy)content='<div class="info-banner amber">本地存储暂不可用。当前操作可继续体验，请先<a href="#settings">导出备份</a>保留记录。</div>'+content;$('#app').innerHTML=shell(content);if(db.settings.large){$$('.card-body,.patient-card').forEach(n=>n.style.fontSize='16px');$$('.sub,.result-text,td,.bubble,.article-card p,.note,.list-line').forEach(n=>n.style.fontSize='13px')}requestAnimationFrame(charts);if(view==='assistant')$('#chat-log').scrollTop=$('#chat-log').scrollHeight;}
function navigate(){const prev=view;view=location.hash.slice(1).split('?')[0]||'overview';if(!pages[view])view='overview';if(prev!==view){search='';filter='全部';window.scrollTo(0,0)}render()}
window.addEventListener('hashchange',navigate);
function formatTime(s){return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function modal(title,body,actions='',wide=false){const overlay=$('#overlay');overlay.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="close" data-action="close" aria-label="关闭">×</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}</section></div>`;requestAnimationFrame(()=>overlay.querySelector('input,select,textarea,button')?.focus());}
function close(){ $('#overlay').innerHTML='' }
document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();$('#sidebar')?.classList.remove('open')}if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();globalSearch()}if(e.key==='Tab'&&$('#overlay .modal')){const list=[...$('#overlay').querySelectorAll('button,a,input,select,textarea')].filter(x=>!x.disabled&&!x.hidden);if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0]?.focus()}}});
function download(name,content,type='text/plain;charset=utf-8'){const blob=new Blob([content],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function csv(rows){return '\ufeff'+rows.map(r=>r.map(v=>{let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}).join(',')).join('\r\n')}
function patientForm(edit=false){if(edit&&!p())return;const x=edit?p():{name:'',age:55,sex:'男',diagnosis:'',side:'右手',stage:'早期',status:'待评估',location:'院内',score:0,progress:0};modal(edit?'编辑体验档案':'新建体验档案',`<p class="info-banner">建议使用昵称或代号。记录仅存于当前浏览器。</p><form id="patient-form" data-edit="${edit}"><div class="form-grid"><label class="field"><span>昵称 / 代号 *</span><input class="input" name="name" maxlength="30" required value="${esc(x.name)}"></label><label class="field"><span>年龄 *</span><input class="input" name="age" type="number" min="1" max="120" required value="${x.age}"></label><label class="field"><span>性别</span><select name="sex">${['男','女','未注明'].map(v=>`<option ${x.sex===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field"><span>患侧</span><select name="side">${['右手','左手','双手'].map(v=>`<option ${x.side===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field full"><span>诊断 / 康复背景（按已有专业诊断填写）*</span><input class="input" name="diagnosis" maxlength="150" required value="${esc(x.diagnosis)}" placeholder="例如：腕部骨折术后"></label>${[['stage','康复阶段',['早期','恢复期','巩固期']],['location','康复场景',['院内','社区','居家']],['status','训练状态',['待评估','训练中','居家训练','待复核']]].map(([name,t,options])=>`<label class="field"><span>${t}</span><select name="${name}">${options.map(v=>`<option ${x[name]===v?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}<label class="field"><span>当前 FMA 上肢总分（0–66）</span><input class="input" name="score" type="number" min="0" max="66" step="1" required value="${x.score}"></label><label class="field"><span>阶段计划进度（0–100%）</span><input class="input" name="progress" type="number" min="0" max="100" step="1" required value="${x.progress}"></label></div><p class="note">FMA 总分应由受训评估人员评定。本字段不是自动评估。</p><button class="btn primary mt" type="submit">${edit?'保存修改':'创建档案'}</button></form>`)}
function assessment(){if(!p())return toast('请先新建体验档案');modal('录入量表评估',`<form id="assessment-form"><div class="info-banner">${esc(p().name)} · ${esc(p().id)}。记录已完成的专业评估，不代替正式量表实施。</div><div class="form-grid"><label class="field"><span>评估日期</span><input class="input" type="date" name="date" required value="${today}"></label><label class="field"><span>FMA 上肢运动功能总分</span><input class="input" name="score" type="number" min="0" max="66" step="1" required value="${p().score}"></label><label class="field"><span>腕关节活动度（°，可选）</span><input class="input" name="wrist" type="number" min="0" max="180" step="0.1"></label><label class="field"><span>握力（kg，可选）</span><input class="input" name="grip" type="number" min="0" max="150" step="0.1"></label><label class="field full"><span>评估人 / 体验审核人 *</span><input class="input" name="assessor" maxlength="50" required placeholder="公开体验请填代号"></label><label class="field full"><span>评估备注</span><textarea name="notes" maxlength="1000"></textarea></label></div><button class="btn primary" type="submit">保存评估记录</button></form>`)}
function createPlan(editId){if(!p())return toast('请先新建体验档案');const old=db.plans.find(x=>x.id===editId),x=p();modal(old?'编辑方案草稿':'生成体验方案草稿',`<div class="info-banner amber">草稿根据档案阶段套用演示模板，不是项目 AI 模型推理或临床处方。审核仅在体验环境生效。</div><form id="plan-form" data-id="${esc(old?.id||'')}"><div class="form-grid"><label class="field full"><span>适用体验档案</span><input class="input" readonly value="${esc(x.name)} · ${esc(x.stage)} · FMA ${x.score}/66"></label><label class="field"><span>体验模式</span><select name="mode">${['被动训练','主动助力','阻力训练'].map(m=>`<option ${(old?.mode||(x.stage==='早期'?'被动训练':'主动助力'))===m?'selected':''}>${m}</option>`).join('')}</select></label><label class="field"><span>目标时长（分钟）</span><input class="input" type="number" name="minutes" min="1" max="60" value="${old?.minutes||20}" required></label><label class="field"><span>界面体验强度（%）</span><input class="input" type="number" name="intensity" min="5" max="60" value="${old?.intensity||30}" required></label><label class="field full"><span>草稿依据与说明 *</span><textarea name="reason" maxlength="2000" required>${esc(old?.reason||`当前档案阶段为${x.stage}，FMA 上肢记录为 ${x.score}/66，已有 ${sessionsFor(x.id).length} 次训练记录。此草稿用于演示模式配置与人工审核流程；模板按阶段默认选择模式，实际模式和参数应由专业人员另行评估。`)}</textarea></label></div><button type="submit" class="btn primary">保存为待审核草稿</button></form>`)}
function reviewPlan(id){const d=db.plans.find(x=>x.id===id);if(!d||d.status!=='待审核')return;modal('审核体验方案',`<div class="info-banner amber">此操作只确认体验草稿，不代表临床签署或真实设备授权。</div><p class="result-text">${esc(d.mode)} · ${d.minutes} 分钟 · 体验强度 ${d.intensity}%<br>${esc(d.reason)}</p><form id="review-form" data-id="${esc(id)}" class="mt"><label class="field"><span>体验审核人 *</span><input class="input" name="reviewer" required maxlength="50" placeholder="填写审核代号"></label><label class="field"><span>审核意见 *</span><textarea name="reviewNote" required maxlength="1000"></textarea></label><div class="row"><button class="btn primary" name="decision" value="已确认" type="submit">确认体验方案</button><button class="btn danger" name="decision" value="已退回" type="submit">退回修改</button></div></form>`)}
function reportText(x){const ss=sessionsFor(x.id),aa=db.assessments.filter(a=>a.patientId===x.id),plans=db.plans.filter(a=>a.patientId===x.id),notes=db.notes.filter(a=>a.patientId===x.id);return `芯护云 · 康复过程记录\n公开体验资料｜非诊疗文件\n生成时间：${when()}\n\n一、体验档案\n代号：${x.name}  编号：${x.id}\n年龄：${x.age}  性别：${x.sex}  患侧：${x.side}\n背景：${x.diagnosis}\n阶段：${x.stage}  场景：${x.location}\n计划进度：${x.progress}%\n\n二、量表记录\n当前 FMA 上肢总分：${x.score}/66\n初始记录：${x.baseline}/66\n${aa.map(a=>`${a.date}：${a.score}/66，记录人 ${a.assessor}。${a.notes}`).join('\n')||'暂无量表记录'}\n\n三、训练记录\n共 ${ss.length} 次，累计 ${(ss.reduce((a,s)=>a+s.seconds,0)/60).toFixed(1)} 分钟\n${ss.slice(-30).map(s=>`${s.date}｜${s.mode}｜${Math.floor(s.seconds/60)}分${s.seconds%60}秒｜完成度 ${s.completion}%｜${s.feeling}｜${s.source}`).join('\n')||'暂无训练记录'}\n\n四、方案与审核\n${plans.map(d=>`${d.date}｜${d.mode}｜${d.minutes} 分钟｜强度 ${d.intensity}%｜${d.status}\n说明：${d.reason}\n审核：${d.reviewer||'未审核'} ${d.reviewNote||''}`).join('\n')||'暂无方案'}\n\n五、病程与感受\n${notes.map(n=>`${n.date}：${n.text}`).join('\n')||'暂无备注'}\n\n六、数据范围与用途\n本报告由当前浏览器保存的体验记录整理，包含内置示例数据或用户自录数据。\n未经专业人员核对，不作为临床评估、诊断、治疗处方或疗效证明。\n公开版未接入真实硬件与项目时序 AI 模型。`}
function createReport(){if(!p())return toast('请先新建体验档案');const r={id:uid('RPT'),patientId:selected,date:when(),status:'待审核',text:reportText(p())};db.reports.push(r);save('生成康复过程报告');render();showReport(r.id)}
function showReport(id){const r=db.reports.find(x=>x.id===id);if(!r)return;modal('康复过程报告',`<div class="report-paper"><h1>芯护云 · 康复记录</h1><p style="text-align:center;font-size:10px;color:#a2b1aa">${esc(r.id)} · ${esc(r.status)}</p><pre>${esc(r.text)}</pre>${r.reviewer?`<p class="note">体验复核：${esc(r.reviewer)} · ${esc(r.reviewNote)}</p>`:''}</div>`,btn('下载 TXT','download-report:'+id,'','download')+btn('打印 / 保存 PDF','print-report','','report')+(r.status==='待审核'?btn('体验复核','review-report:'+id,'primary','check'):''),true)}
function deviceBind(id){if(!p())return toast('请先创建档案');const d=db.devices.find(x=>x.id===id);modal('登记 / 绑定体验设备',`<form id="device-form" data-id="${esc(d?.id||'')}"><label class="field"><span>设备编号 *</span><input class="input" name="id" required pattern="(?:[A-Za-z0-9_]|-){2,40}" maxlength="40" value="${esc(d?.id||'')}" ${d?'readonly':''} placeholder="如 ZX-006（字母、数字、下划线、短横线）"></label><label class="field"><span>设备名称 *</span><input class="input" name="name" maxlength="80" required value="${esc(d?.name||'肌电采集器 + 康复手套')}"></label><label class="field"><span>绑定体验档案</span><select name="patientId"><option value="">暂不绑定</option>${db.patients.map(x=>`<option value="${esc(x.id)}" ${(d?.patientId||selected)===x.id?'selected':''}>${esc(x.name)} · ${esc(x.id)}</option>`).join('')}</select></label><p class="note">仅建立本地资产关系，不代表已通过蓝牙或网关连接硬件。</p><button class="btn primary mt" type="submit">保存设备绑定</button></form>`)}
function deviceDetails(id){const d=db.devices.find(x=>x.id===id);if(!d)return;modal('设备维护 · '+d.id,`${line('设备',esc(d.name))}${line('固件记录',esc(d.firmware))}${line('状态',esc(d.status))}<div class="timeline mt">${d.maintenance.map(m=>`<div class="timeline-item"><h3>${esc(m.date)}</h3><p>${esc(m.text)}</p></div>`).join('')||'<p class="note">暂无维护记录。</p>'}</div><form id="maintenance-form" data-id="${esc(id)}" class="mt"><label class="field"><span>巡检 / 维护事项 *</span><textarea name="text" required maxlength="1500" placeholder="填写观察到的问题、处理过程和结果"></textarea></label><label class="field"><span>资产记录状态</span><select name="status"><option>模拟在线</option><option>需巡检</option><option>维护中</option><option>离线记录</option></select></label><button class="btn primary" type="submit">保存维护记录</button></form>`)}
function article(id){const a=articles.find(x=>x.id===id);if(!a)return;modal(a.title,`<article class="article-body">${tag(a.category)}<p>${a.description}</p>${a.sections.map(([title,text])=>`<h3>${title}</h3><p>${text}</p>`).join('')}<p class="note">此内容为一般知识与平台使用说明；请遵循专业人员指导及对应设备说明书。${a.id==='fma'?'<br>评估工具参考：<a href="https://www.gu.se/en/neuroscience-physiology/fugl-meyer-assessment" target="_blank" rel="noopener">哥德堡大学 Fugl-Meyer Assessment</a>':''}</p></article>`,btn('阅读完成','close','primary'))}
function answer(q){const x=p();if(/摘要|报表|报告|记录统计/.test(q))return x?`当前体验档案：${x.name}（${x.id}）。\n康复阶段：${x.stage}；FMA 上肢记录：${x.score}/66，初始记录 ${x.baseline}/66。\n累计 ${sessionsFor(x.id).length} 次训练，累计 ${(sessionsFor(x.id).reduce((a,s)=>a+s.seconds,0)/60).toFixed(1)} 分钟（包含示例记录）。\n待审核方案：${db.plans.filter(d=>d.patientId===x.id&&d.status==='待审核').length} 份。\n\n可在“康复报告”生成并下载完整记录。本摘要按本地记录整理，不评价临床疗效。`:'请先创建体验档案。';let a;if(/疼|痛|不适|疲劳|麻木/.test(q))return '训练中出现疼痛、明显不适、异常疲劳或设备异常时，应停止训练并联系康复师。不要自行增加训练强度。\n\n本助手无法根据症状或肌电图判断病因，也不能为您制定治疗方案。\n参考条目：训练课堂《把每一次训练，变成可追踪的进步》。';if(/清洁|消毒|维护|浸水/.test(q))a=articles.find(a=>a.id==='clean');else if(/电极|佩戴|手套|准备/.test(q))a=articles.find(a=>a.id==='wear');else if(/FMA|评分|量表|评估/i.test(q))a=articles.find(a=>a.id==='fma');else if(/肌电|RMS|波形|信号/i.test(q))a=articles.find(a=>a.id==='emg');else if(/居家|出院|提醒|随访/.test(q))a=articles.find(a=>a.id==='home');else if(/训练|模式|方案|强度/.test(q))a=articles.find(a=>a.id==='train');if(!a)return '当前内置知识库没有匹配到这个问题。我可以协助查询：设备佩戴与清洁、训练记录、FMA 总分记录、肌电特征说明、居家提醒和当前档案摘要。\n\n具体诊疗与参数调整请咨询专业人员。此处未调用外部大模型。';return a.sections.map(([t,s])=>`${t}：${s}`).join('\n\n')+`\n\n参考条目：康复课堂《${a.title}》。`}
function ask(q){chat.push({self:true,text:q},{self:false,text:answer(q)});if(chat.length>40)chat=chat.slice(-40);if(view!=='assistant')location.hash='assistant';else render()}
function scope(){modal('功能与数据说明',`<div class="article-body"><h3>可以直接使用</h3><p>公众查阅、多页面体验、档案增删改查、量表总分录入、训练计时及感受记录、方案草稿与体验审核、报告下载与打印、设备绑定与维护、知识检索问答、随访提醒、统计分析和数据备份。</p><h3>计算能力</h3><p>导入 CSV 后实际计算 RMS、平均绝对值、峰峰值、过零率和采样率；质量提示采用透明规则，不能替代医学异常识别模型。</p><h3>数据范围</h3><p>每位访客使用独立的浏览器本地空间。页面公开，体验档案不跨访客共享。角色视图切换不是身份认证，留言不发送给真实医生。</p><h3>真实服务仍需接入</h3><p>机构数据库、真实用户及权限、硬件网关和安全协议、项目时序模型、远程通信和离线消息服务。附件没有提供这些服务与密钥，本版没有将模拟功能标记为真实连接。</p></div>`,btn('知道了','close','primary'),true)}
function integration(){modal('设备与模型接入约定',`<div class="article-body"><h3>现在可用：离线采样数据</h3><pre class="code">time_ms,flexor_mv,extensor_mv\n0,0.012,-0.005\n1,0.018,0.003\n2,0.009,0.007</pre><p>UTF-8 CSV，毫秒时间戳，严格递增，两个通道单位为 mV。采样间隔、量程和滤波方式由原始设备说明确定。</p><h3>设备网关需要提供</h3><p>传输方式（蓝牙 / 串口 / HTTPS）、服务与特征 UUID 或串口帧结构、设备身份验证、采样率及通道映射、校准关系、数据时序与掉线处理。真实控制还需要助力与阻力的物理单位、范围、安全互锁和急停协议。</p><h3>模型服务需要提供</h3><p>模型权重或安全推理 API、输入窗口及预处理、输出标签与置信度、验证集与适用人群、错误和超时约定。密钥必须保存在服务端，不能写入网页。</p><h3>机构服务需要提供</h3><p>用户角色、机构隔离与患者授权、可靠数据库和备份、日志、医患消息和报告审核身份。完成这些接入后，才能把公开体验升级为真实业务服务。</p></div>`,btn('下载 CSV 模板','sample-csv','','download')+btn('关闭','close','primary'),true)}
function globalSearch(){modal('全局搜索',`<input id="global-search-input" class="input" style="width:100%" placeholder="搜索患者、功能或知识…" aria-label="全局搜索"><div id="global-results" class="mt">输入关键词开始查找。</div>`)}
function compute(rows){const feature=index=>{const a=rows.map(r=>r[index]),n=a.length,mean=a.reduce((s,v)=>s+v,0)/n,rms=Math.sqrt(a.reduce((s,v)=>s+v*v,0)/n),mav=a.reduce((s,v)=>s+Math.abs(v),0)/n,min=Math.min(...a),max=Math.max(...a),variance=a.reduce((s,v)=>s+(v-mean)**2,0)/n;let crosses=0,jumps=0,extremes=0;const sd=Math.sqrt(variance),tol=Math.max((max-min)*.0001,1e-9);for(let i=1;i<n;i++){if((a[i]>=0)!==(a[i-1]>=0))crosses++;if(sd>0&&Math.abs(a[i]-a[i-1])>6*sd)jumps++;if(Math.abs(a[i]-max)<=tol||Math.abs(a[i]-min)<=tol)extremes++}return {rms,mav,p2p:max-min,zcr:crosses/(n-1),sd,jumps,extremeRate:extremes/n}};const dt=rows.slice(1).map((r,i)=>r[0]-rows[i][0]),step=dt.reduce((s,n)=>s+n,0)/dt.length,rate=1000/step,jitter=Math.max(...dt.map(n=>Math.abs(n-step)))/step*100,flex=feature(1),ext=feature(2),warnings=[];for(const [name,f]of [['屈肌',flex],['伸肌',ext]]){if(f.p2p<.00001)warnings.push({title:name+'通道接近平直',text:'峰峰值 < 0.00001 mV。检查采样内容、通道和数据导出设置。'});if(f.jumps)warnings.push({title:name+'通道出现孤立跳变',text:`相邻点变化超过该通道标准差的 6 倍，共 ${f.jumps} 次。此规则不识别疾病。`});if(f.extremeRate>.15&&f.p2p>.00001)warnings.push({title:name+'通道极值重复较多',text:'超过 15% 样本接近整体极大或极小值，可能与量化、削顶或规则波形有关，需核对原始采集。'});}if(jitter>5)warnings.push({title:'采样间隔不均匀',text:`相对平均间隔的最大偏离为 ${jitter.toFixed(1)}%。检查时间单位、丢包或导出方式。`});if(!warnings.length)warnings.push({title:'未触发当前数据质量规则',text:'未发现平直、显著孤立跳变、重复极值或明显时间间隔不均。此结果不表示信号无医学异常。'});return {flex,ext,rate,jitter,warnings}}
function sampleRows(noisy=false){return Array.from({length:2000},(_,i)=>[i,Math.sin(i*.34)*.16*(.55+.4*Math.sin(i*.008))+Math.sin(i*.77)*.034+(noisy&&i===1030?3:0),Math.sin(i*.27+.8)*.12*(.5+.4*Math.sin(i*.01))]);}
function loadEmg(rows,name,source='file'){emg={rows,name,source,stats:compute(rows)};render();toast('已完成波形解析与特征计算')}
async function parseCsv(file){if(!file||file.size>5*1024*1024)throw Error('文件须小于 5 MB');const text=(await file.text()).replace(/^\ufeff/,'').trim(),lines=text.split(/\r?\n/).filter(l=>l.trim());if(lines.length<4||lines.length>50001)throw Error('请提供 3–50,000 个采样点');const split=l=>l.split(',').map(s=>s.trim().replace(/^"|"$/g,''));const headers=split(lines.shift()).map(h=>h.toLowerCase());if(headers.join(',')!=='time_ms,flexor_mv,extensor_mv')throw Error('CSV 表头须为 time_ms,flexor_mv,extensor_mv');let last=-Infinity;const rows=lines.map((l,i)=>{const parts=split(l);if(parts.length!==3||parts.some(v=>v===''))throw Error(`第 ${i+2} 行必须有三个非空数值`);const r=parts.map(Number);if(r.some(x=>!Number.isFinite(x))||r[0]<0||r[0]<=last||Math.abs(r[1])>1000||Math.abs(r[2])>1000)throw Error(`第 ${i+2} 行数值无效、幅值过大或时间没有递增`);last=r[0];return r});loadEmg(rows,file.name)}
function saveSession(){try{if(session.seconds||session.running){localStorage.setItem(SESSION_KEY,JSON.stringify({seconds:session.seconds,mode:session.mode,intensity:session.intensity,minutes:session.minutes,patientId:session.patientId,checked:session.checked,startedDate:session.startedDate,runId:session.runId,updatedAt:when()}))}else localStorage.removeItem(SESSION_KEY)}catch{storageHealthy=false}}
function pause(){session.seconds=elapsedSeconds(session);session.baseSeconds=session.seconds;session.running=false;session.startedAt=null;clearInterval(session.interval);session.interval=null;saveSession()}
function resetSession(){pause();session.seconds=0;session.baseSeconds=0;session.patientId=null;session.runId=null;session.startedDate=null;restored=false;saveSession()}
function tick(){const before=session.seconds;session.seconds=elapsedSeconds(session);if(before!==session.seconds)saveSession();$('#pending-time')&&($('#pending-time').textContent=formatTime(session.seconds));$('#timer')&&($('#timer').textContent=formatTime(session.seconds));$('#session-bar')&&($('#session-bar').style.width=Math.min(100,session.seconds/(session.minutes*60)*100)+'%');$('#session-progress')&&($('#session-progress').textContent=Math.min(100,Math.round(session.seconds/(session.minutes*60)*100))+'%');if(session.seconds>=session.minutes*60){pause();render();finishTraining()}}
function toggleTraining(){if(session.running){pause();render();return}if(session.seconds>=session.minutes*60)return finishTraining();if(!session.checked)return toast('请先勾选模拟训练说明');if(!p())return toast('请先创建体验档案');session.patientId=selected;session.runId=session.runId||uid('S');session.startedDate=session.startedDate||localDate();session.baseSeconds=session.seconds;session.startedAt=Date.now();session.running=true;restored=false;session.interval=setInterval(tick,250);saveSession();render()}
function finishTraining(){if(!session.seconds)return toast('先开始体验计时，再结束并记录');pause();render();modal('结束训练并记录感受',`<form id="finish-form"><div class="info-banner">实际计时：${formatTime(session.seconds)} · ${esc(session.mode)}<br>目标 ${session.minutes} 分钟 · ${esc(db.patients.find(x=>x.id===session.patientId)?.name||p()?.name)}</div><label class="field"><span>本次训练感受</span><select name="feeling"><option>无明显不适</option><option>轻度疲劳，已休息</option><option>出现不适，已停止体验</option><option>仅测试界面操作</option></select></label><label class="field"><span>补充记录</span><textarea name="notes" maxlength="1500" placeholder="如有需要，记录希望与专业人员沟通的事项"></textarea></label><button type="submit" class="btn primary">保存训练记录</button></form>`)}
function nowTime(){return new Date().toLocaleTimeString('en-GB',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hour12:false})}
function checkpoint(reason){
 try{localStorage.setItem(RECOVERY_KEY,JSON.stringify({date:when(),reason,data:db}));return true}
 catch{toast('恢复点保存失败。请先下载备份，释放浏览器空间后再试。');return false}
}
function recovery(){
 let snap;try{snap=JSON.parse(localStorage.getItem(RECOVERY_KEY));validateWorkspace(snap.data)}catch{return toast('还没有可恢复的数据；导入、恢复示例或删除档案前会自动建立恢复点。')}
 modal('恢复点',`<div class="info-banner">${esc(snap.date)} · ${esc(snap.reason)}</div><p class="result-text">包含 ${snap.data.patients.length} 份档案、${snap.data.sessions.length} 条训练与 ${snap.data.tasks.length} 条随访。恢复会替换当前空间，当前记录会成为新的恢复点。</p>`,btn('取消','close')+btn('下载此恢复点','download-recovery','','download')+btn('恢复这份数据','restore-recovery','primary'));
 $('[data-action=download-recovery]').onclick=()=>download('芯护云-恢复点.json',JSON.stringify(snap.data,null,2),'application/json');
 $('[data-action=restore-recovery]').onclick=()=>{if(session.running||session.seconds)return toast('请先保存或重置当前训练');const current=db;if(!checkpoint('恢复点替换前'))return;db=snap.data;selected=db.settings.selectedPatient||db.patients[0]?.id;if(!save('恢复本地数据')){db=current;selected=db.settings.selectedPatient||db.patients[0]?.id;return}resetSession();close();render();toast('已恢复，替换前的数据仍可通过恢复点找回')};
}
function downloadBackup(){db.settings.lastBackupAt=when();save();download('芯护云-完整备份-'+localDate()+'.json',JSON.stringify(db,null,2),'application/json');if(view==='settings')render();toast('备份下载已开始，包含档案、训练、报告与随访')}
function guide(){modal('从第一份档案开始',`<div class="guide-modal">${[['patients','01','建立体验档案','用昵称创建档案，记录康复背景。'],['assistant','02','整理并确认方案','查看草稿依据，填写体验审核意见。'],['training','03','完成一段模拟训练','计时、暂停、保存感受，中断后可恢复。'],['reports','04','留下一份过程报告','汇总已保存记录，下载或打印。']].map(([route,no,title,desc])=>`<a class="guide-row" href="#${route}"><span>${no}</span><div><strong>${title}</strong><small>${desc}</small></div>${icon('arrow')}</a>`).join('')}</div>`,btn('开始建立档案','guide-start','primary','plus'))}
function onboarding(){
 if(db.settings.onboardingHidden)return '';
 const steps=[['patients','建立档案',db.patients.some(x=>!x.id.startsWith('DEMO-'))],['assistant','确认方案',db.plans.some(x=>x.status==='已确认')],['training','记录训练',db.sessions.some(x=>x.source!=='示例训练')],['reports','生成报告',db.reports.length>0]],count=steps.filter(x=>x[2]).length;
 return `<section class="journey-guide"><div class="row between"><span><b>快速开始</b><small>完成一次完整体验 · ${count}/4</small></span><button class="link" data-action="guide-hide" aria-label="收起快速开始">收起 ×</button></div><div class="journey-steps">${steps.map(([route,label,done],i)=>`<a href="#${route}" class="${done?'complete':''}"><span>${done?'✓':String(i+1).padStart(2,'0')}</span>${label}${icon('arrow')}</a>`).join('')}</div></section>`;
}
function calendarTask(t){const state=taskStatus(t,today,nowTime()),person=db.patients.find(x=>x.id===t.patientId);return `<article class="followup-task ${t.done?'done':''}"><div class="row between"><span class="task-time">${esc(t.time)} <small>${esc(t.kind||'随访提醒')}</small></span>${tag(state,state==='已逾期'?'red':state==='今日待办'?'amber':t.done?'gray':'blue')}</div><h3>${esc(t.title)}</h3><p>${esc(person?.name||'已删除档案')} · ${esc(t.date)}</p>${t.notes?`<div class="task-notes">${esc(t.notes)}</div>`:''}<div class="row task-actions">${btn(t.done?'重新打开':'标记完成','task-toggle:'+t.id,'tiny soft',t.done?'clock':'check')}${btn('编辑','task-edit:'+t.id,'tiny')}${btn('删除','task-delete:'+t.id,'tiny')}</div></article>`}
function followupsPage(){
 const scoped=db.tasks.filter(t=>calendarPatient==='全部'||t.patientId===calendarPatient),list=scoped.filter(t=>taskFilter==='全部'||taskFilter==='未完成'&&!t.done||taskFilter==='已完成'&&t.done||taskFilter==='已逾期'&&taskStatus(t,today,nowTime())==='已逾期'),dayTasks=list.filter(t=>t.date===calendarDay).sort((a,b)=>a.time.localeCompare(b.time)),days=calendarDays(calendarMonth),next=scoped.filter(t=>!t.done).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).slice(0,5);
 return `${head('FOLLOW-UP CALENDAR','随访计划','把训练提醒、阶段复评和待沟通事项安排清楚。',btn('导出日历','export-calendar','','download')+btn('新建随访','new-task','primary','plus'))}<div class="followup-summary">${[['今日安排',scoped.filter(t=>t.date===today&&!t.done).length,'clock'],['待完成',scoped.filter(t=>!t.done).length,'report'],['已逾期',scoped.filter(t=>taskStatus(t,today,nowTime())==='已逾期').length,'warning'],['已完成',scoped.filter(t=>t.done).length,'check']].map(([label,num,ic])=>`<div>${icon(ic)}<span>${label}<strong>${num}</strong></span></div>`).join('')}</div><div class="search-row"><select id="calendar-patient" aria-label="按档案筛选随访"><option value="全部">全部体验档案</option>${db.patients.map(x=>`<option value="${esc(x.id)}" ${calendarPatient===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><div class="tabs followup-filters">${['全部','未完成','已逾期','已完成'].map(s=>`<button data-followup-filter="${s}" class="${taskFilter===s?'active':''}">${s}</button>`).join('')}</div></div><div class="calendar-layout"><section class="card calendar-card"><div class="calendar-toolbar"><h2>${calendarMonth.slice(0,4)} 年 ${Number(calendarMonth.slice(5))} 月</h2><div class="row"><button class="icon-button" data-action="calendar-prev" aria-label="上个月">‹</button><button class="btn tiny" data-action="calendar-today">今天</button><button class="icon-button" data-action="calendar-next" aria-label="下个月">›</button></div></div><div class="calendar-week">${['一','二','三','四','五','六','日'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${days.map(date=>{const events=list.filter(t=>t.date===date),outside=date.slice(0,7)!==calendarMonth;return `<button class="calendar-day ${outside?'outside':''} ${date===today?'today':''} ${date===calendarDay?'selected':''}" data-calendar-day="${date}" aria-label="${date}，${events.length} 项安排" aria-pressed="${date===calendarDay}"><span>${Number(date.slice(-2))}</span><div class="calendar-events">${events.slice(0,2).map(t=>`<small class="${t.done?'finished':''}">${esc(t.title)}</small>`).join('')}${events.length>2?`<small>还有 ${events.length-2} 项</small>`:''}</div>${events.length?`<i class="calendar-count">${events.length}</i>`:''}</button>`}).join('')}</div></section><div class="stack">${card(esc(calendarDay)+' 的安排',dayTasks.map(calendarTask).join('')||`<div class="empty calendar-empty">${icon('clock')}<p>这一天还没有匹配的安排</p><button class="btn soft mt" data-action="new-task">添加一项安排</button></div>`,tag(dayTasks.length+' 项'))}${card('接下来关注',next.length?next.map(t=>`<button class="upcoming-task" data-calendar-day="${esc(t.date)}"><i class="dot"></i><span><strong>${esc(t.title)}</strong><small>${esc(t.date)} ${esc(t.time)}</small></span>${icon('arrow')}</button>`).join(''):'<p class="notice-empty">当前没有待完成事项</p>')}</div></div><p class="note">计划保存在本浏览器；导出的 .ics 文件可导入支持日历文件的应用，每项默认预留 30 分钟。网页提醒仅在页面打开时检查，系统日历提醒由所用日历应用决定。</p>`;
}
function taskForm(id){
 if(!db.patients.length)return toast('请先建立体验档案，再添加随访');
 const task=db.tasks.find(x=>x.id===id),x=task||{title:'',date:calendarDay,time:db.settings.remind,kind:'阶段复评',notes:'',patientId:selected};
 modal(task?'编辑随访安排':'新建随访安排',`<form id="followup-form" data-id="${esc(task?.id||'')}"><div class="form-grid"><label class="field full"><span>关联体验档案</span><select name="patientId">${db.patients.map(p=>`<option value="${esc(p.id)}" ${x.patientId===p.id?'selected':''}>${esc(p.name)} · ${esc(p.id)}</option>`).join('')}</select></label><label class="field full"><span>安排标题 *</span><input class="input" name="title" maxlength="100" required value="${esc(x.title)}" placeholder="例如：复评时携带本周训练记录"></label><label class="field"><span>日期 *</span><input class="input" type="date" name="date" required value="${esc(x.date)}"></label><label class="field"><span>时间 · 北京时间 *</span><input class="input" type="time" name="time" required value="${esc(x.time)}"></label><label class="field full"><span>类型</span><select name="kind">${['阶段复评','训练提醒','设备巡检','待沟通事项','随访提醒'].map(k=>`<option ${x.kind===k?'selected':''}>${k}</option>`).join('')}</select></label><label class="field full"><span>补充说明</span><textarea name="notes" maxlength="2000">${esc(x.notes)}</textarea></label></div><p class="note">这是本地计划记录，保存不会发送预约或通知给真实医疗机构。</p><button class="btn primary mt" type="submit">保存随访安排</button></form>`);
}
function moveCalendar(offset){const [y,m]=calendarMonth.split('-').map(Number);calendarMonth=new Date(Date.UTC(y,m-1+offset,1)).toISOString().slice(0,7);calendarDay=calendarMonth+'-01';render()}
function handleFollowupAction(action){
 const [kind,id]=action.split(':'),task=db.tasks.find(t=>t.id===id);
 if(kind==='task-edit'){taskForm(id);return true}
 if(kind==='task-toggle'&&task){task.done=!task.done;task.notified=false;save(task.done?'完成随访事项':'重新打开随访事项');render();return true}
 if(kind==='task-delete'&&task){modal('删除随访安排',`<p class="result-text">删除“${esc(task.title)}”？其他记录会保留。</p>`,btn('取消','close')+btn('确认删除','confirm-task-delete','danger'));$('[data-action=confirm-task-delete]').onclick=()=>{db.tasks=db.tasks.filter(t=>t.id!==id);save('删除随访安排');close();render()};return true}
 return false;
}
const actionHandlers={
 'new-task':()=>taskForm(), 'calendar-prev':()=>moveCalendar(-1),'calendar-next':()=>moveCalendar(1),'calendar-today':()=>{calendarMonth=today.slice(0,7);calendarDay=today;render()},
 'export-calendar':()=>{const tasks=db.tasks.filter(t=>calendarPatient==='全部'||t.patientId===calendarPatient);if(!tasks.length)return toast('先添加随访安排，再导出日历');download('芯护云-随访计划.ics',calendarExport(tasks,db.patients),'text/calendar;charset=utf-8');toast('日历已导出，时间按北京时间转换')},
 'recovery':recovery,'guide':guide,'guide-start':()=>{close();patientForm()},'guide-hide':()=>{db.settings.onboardingHidden=true;save();render()},
 close,menu:()=>$('#sidebar').classList.toggle('open'),scope,integration,'global-search':globalSearch,
 role:()=>modal('选择体验视图',`<p class="result-text">公众无需账号即可体验。这里切换界面，不进行身份认证，所有数据仍保存在当前浏览器。</p><div class="row mt"><a class="btn primary" href="#overview" data-close-link>医护工作台</a><a class="btn" href="#home" data-close-link>患者康复页</a></div>`),
 'new-patient':()=>patientForm(), 'edit-patient':()=>patientForm(true),assessment,'new-plan':()=>createPlan(),'new-report':createReport,'bind-device':()=>deviceBind(),
 notifications:()=>modal('提醒与待办',`<div class="timeline"><div class="timeline-item"><h3>${db.plans.filter(x=>x.status==='待审核').length} 份方案待审核</h3><p>可在智能辅助页面查看草稿与依据。</p></div><div class="timeline-item"><h3>${db.reports.filter(x=>x.status==='待审核').length} 份报告待复核</h3><p>可下载并核对实际保存的训练与评估信息。</p></div><div class="timeline-item"><h3>${db.tasks.filter(t=>!t.done&&t.date<=today).length} 个本地待办</h3><p>在“我的康复”查看随访和提醒。</p></div></div>`,btn('关闭','close','primary')),
 'toggle-training':toggleTraining,'finish-training':finishTraining,'reset-training':()=>{if(!session.seconds&&!session.running)return;modal('放弃这段训练？','<p class="result-text">这段训练尚未归档。可以继续训练，或通过“结束并记录”保存后再开始新训练。</p>',btn('继续保留','close')+btn('放弃并重置','discard-session','danger'))},'discard-session':()=>{resetSession();close();render()},
 'game-hit':()=>{gameHits++;$('#game-count').textContent=gameHits;const target=$('.game-target');target.style.transform=`translateX(${(gameHits%3-1)*50}px)`},
 'load-plan':()=>{const plan=db.plans.filter(x=>x.patientId===selected&&x.status==='已确认').at(-1);if(!plan)return toast('当前没有已确认方案，请先在智能辅助中生成并审核');if(session.running||session.seconds)return toast('请先记录或重置当前训练，再加载新方案');session.mode=plan.mode;session.intensity=plan.intensity;session.minutes=plan.minutes;render();toast('已加载体验方案参数')},
 'sample-emg':()=>loadEmg(sampleRows(),'内置肌电波形 · 2 秒','sample'),
 'sample-csv':()=>download('芯护云-肌电采样模板.csv','time_ms,flexor_mv,extensor_mv\r\n'+sampleRows().slice(0,300).map(r=>r.map((v,i)=>i?v.toFixed(6):v).join(',')).join('\r\n'),'text/csv;charset=utf-8'),
 'export-emg':()=>{if(emg)download('芯护云-肌电特征.json',JSON.stringify({name:emg.name,samples:emg.rows.length,source:emg.source,stats:emg.stats,method:'浏览器计算及启发式质量规则，非医学异常模型'},null,2),'application/json')},
 'export-sessions':()=>download('芯护云-训练记录.csv',csv([['日期','档案编号','模式','时长秒','完成度百分比','感受','来源'],...db.sessions.map(s=>[s.date,s.patientId,s.mode,s.seconds,s.completion,s.feeling,s.source])]),'text/csv;charset=utf-8'),
 'export-patients':()=>download('芯护云-体验档案.csv',csv([['编号','代号','年龄','性别','康复背景','患侧','阶段','状态','FMA总分','计划进度'],...db.patients.map(x=>[x.id,x.name,x.age,x.sex,x.diagnosis,x.side,x.stage,x.status,x.score,x.progress])]),'text/csv;charset=utf-8'),
 'export-profile':()=>p()&&download('芯护云-'+p().id+'-档案.txt',reportText(p())),
 'export-analytics':()=>{const since=localDate(new Date(Date.now()-(range-1)*86400000)),s=db.sessions.filter(s=>s.date>=since);download('芯护云-过程统计.csv',csv([['统计范围','训练记录数','覆盖档案数','平均时长分钟','平均完成度'],[since+' 至 '+today,s.length,new Set(s.map(s=>s.patientId)).size,(s.reduce((a,x)=>a+x.seconds,0)/Math.max(1,s.length)/60).toFixed(2),(s.reduce((a,x)=>a+x.completion,0)/Math.max(1,s.length)).toFixed(1)]]),'text/csv;charset=utf-8')},
 backup:downloadBackup,
 'reset-data':()=>modal('恢复初始示例',`<p class="result-text">此操作将用初始示例替换本浏览器中的全部体验记录。建议先下载备份。</p>`,btn('先下载备份','backup')+btn('确认恢复','confirm-reset','danger')),
 'confirm-reset':()=>{if(!checkpoint('恢复示例前'))return;resetSession();db=seed();selected=db.patients[0].id;save('恢复初始示例');close();render();toast('已恢复初始示例')},
 'clear-data':()=>modal('清空本地数据',`<p class="result-text">将删除此浏览器中的所有体验档案、训练、量表、报告与提醒。此操作不能撤销。</p>`,btn('先下载备份','backup')+btn('确认清空','confirm-clear','danger')),
 'confirm-clear':()=>{if(!checkpoint('清空记录前'))return;resetSession();db=seed();for(const k of ['patients','sessions','assessments','devices','plans','reports','notes','messages','tasks','audit'])db[k]=[];db.checks={};selected=null;save();close();render();toast('本地体验记录已清空')},
 'delete-patient':()=>{if(!p())return;modal('删除体验档案',`<p class="result-text">将删除 ${esc(p().name)} 的档案及关联训练、评估、报告、方案和留言。设备资产保留并解除绑定。</p>`,btn('取消','close')+btn('确认删除','confirm-delete','danger'))},
 'confirm-delete':()=>{if((session.running||session.seconds)&&session.patientId===selected)return toast('请先保存或重置此档案的训练');if(!checkpoint('删除档案前'))return;const id=selected;for(const k of ['patients','sessions','assessments','plans','reports','notes','messages','tasks'])db[k]=db[k].filter(x=>k==='patients'?x.id!==id:x.patientId!==id);db.devices.forEach(d=>{if(d.patientId===id)d.patientId=''});selected=db.patients[0]?.id;save('删除体验档案');close();location.hash='patients';render();toast('档案及关联记录已删除')},
 feedback:()=>modal('记录今日感受',`<form id="feedback-form"><label class="field"><span>训练感受 / 希望沟通的事项</span><textarea name="text" required maxlength="1500"></textarea></label><button class="btn primary" type="submit">保存到照护备注</button></form>`),
 'print-report':()=>window.print()
};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action],[data-patient],[data-tab],[data-mode],[data-question],[data-article],[data-assistant-role],[data-signal],[data-report],[data-close-link],[data-calendar-day],[data-followup-filter]');if(!el)return;if(el.dataset.calendarDay){calendarDay=el.dataset.calendarDay;calendarMonth=calendarDay.slice(0,7);render();return}if(el.dataset.followupFilter){taskFilter=el.dataset.followupFilter;render();return}if(el.hasAttribute('data-close-link')){close();return}if(el.dataset.patient){close();if((session.running||session.seconds)&&el.dataset.patient!==selected)return toast('切换档案前请保存或重置当前训练');selected=el.dataset.patient;save();detailTab='overview';location.hash='detail';render();return}if(el.dataset.tab){detailTab=el.dataset.tab;render();return}if(el.dataset.mode){if(session.running||session.seconds)return toast('先保存或重置当前训练，再更换模式');session.mode=el.dataset.mode;render();return}if(el.dataset.question){ask(el.dataset.question);return}if(el.dataset.article){article(el.dataset.article);return}if(el.dataset.assistantRole){assistantRole=el.dataset.assistantRole;chat=[];render();return}if(el.dataset.signal){$$('[data-signal]').forEach(b=>b.classList.toggle('active',b===el));drawLines('signal-chart',sampleRows(el.dataset.signal==='noisy'),true);return}if(el.dataset.report){showReport(el.dataset.report);return}const act=el.dataset.action;if(!act)return;if(handleFollowupAction(act))return;if(actionHandlers[act]){actionHandlers[act]();return}const [kind,id]=act.split(':');if(kind==='review-plan')reviewPlan(id);if(kind==='edit-plan')createPlan(id);if(kind==='device')deviceDetails(id);if(kind==='rebind')deviceBind(id);if(kind==='download-report'){const r=db.reports.find(x=>x.id===id);if(r)download(r.id+'.txt',r.text+(r.reviewer?'\n体验复核：'+r.reviewer+' '+r.reviewNote:''))}if(kind==='review-report'){const r=db.reports.find(x=>x.id===id);if(!r)return;modal('体验复核报告',`<form id="report-review-form" data-id="${esc(id)}"><div class="info-banner">只记录体验复核，不代表真实医师签署。</div><label class="field"><span>复核代号 *</span><input class="input" name="reviewer" maxlength="50" required></label><label class="field"><span>复核意见 *</span><textarea name="reviewNote" required maxlength="1000"></textarea></label><button class="btn primary" type="submit">完成体验复核</button></form>`)}});
document.addEventListener('input',e=>{const n=e.target;if(n.id==='patient-search'||n.id==='knowledge-search'){const pos=n.selectionStart;search=n.value;render();const input=$('#'+n.id);input.focus();input.setSelectionRange(pos,pos)}if(n.id==='intensity'){if(session.running||session.seconds){n.value=session.intensity;return toast('先保存或重置当前训练，再更换强度')}session.intensity=+n.value;$('#intensity-label').textContent=n.value+'%'}if(n.id==='global-search-input'){const q=n.value.trim().toLowerCase();const list=[...db.patients.map(x=>({label:x.name+' · '+x.id,desc:x.diagnosis,html:`data-patient="${esc(x.id)}"`})),...navs.map(([id,ic,label])=>({label,desc:'平台功能',html:`data-goto="${id}"`})),...articles.map(a=>({label:a.title,desc:a.description,html:`data-article="${a.id}"`}))].filter(x=>q&&`${x.label}${x.desc}`.toLowerCase().includes(q));$('#global-results').innerHTML=list.slice(0,10).map(x=>`<button class="question-chip" ${x.html}>${esc(x.label)}<small class="muted" style="display:block;font-size:10px">${esc(x.desc)}</small></button>`).join('')||'<p class="note">没有匹配项。</p>';$('[data-goto]').forEach(b=>b.onclick=()=>{close();location.hash=b.dataset.goto})}});
document.addEventListener('change',async e=>{const n=e.target;if(n.id==='calendar-patient'){calendarPatient=n.value;render()}if(n.id==='patient-select'){if((session.running||session.seconds)&&n.value!==selected){n.value=selected;return toast('切换档案前请保存或重置当前训练')}selected=n.value;save();render()}if(n.id==='patient-filter'){filter=n.value;render()}if(n.id==='analytics-range'){range=+n.value;render()}if(n.id==='duration'){if(session.running||session.seconds){n.value=session.minutes;return toast('先保存或重置当前训练，再更换目标时长')}session.minutes=+n.value}if(n.id==='training-check')session.checked=n.checked;if(n.id==='large-text'){db.settings.large=n.checked;save();render()}if(n.id==='reminder-time'){db.settings.remind=n.value||'09:00';save()}if(n.dataset.care){db.checks[today+'-'+selected+'-'+n.dataset.care]=n.checked;save('更新今日任务')}if(n.dataset.task){const t=db.tasks.find(t=>t.id===n.dataset.task);if(t){t.done=n.checked;save('更新提醒任务')}}if(n.id==='emg-file'){try{await parseCsv(n.files[0])}catch(err){toast(err.message)}n.value=''}if(n.id==='backup-file'){if(session.running||session.seconds){n.value='';return toast('请先保存或重置当前训练，再导入备份')}try{if(!n.files[0]||n.files[0].size>10*1024*1024)throw Error('备份须小于 10 MB');const incoming=validateWorkspace(JSON.parse(await n.files[0].text()));modal('导入备份并替换',`<p class="result-text">检测到 ${incoming.patients.length} 份档案、${incoming.sessions.length} 条训练、${incoming.reports.length} 份报告。确认后替换当前本地体验数据。</p>`,btn('备份当前数据','backup')+btn('确认导入','do-import','primary'));$('[data-action="do-import"]').onclick=()=>{if(!checkpoint('导入备份前'))return;const current=db;db=incoming;selected=db.settings.selectedPatient||db.patients[0]?.id;if(!save('导入体验备份')){db=current;selected=db.settings.selectedPatient||db.patients[0]?.id;return}resetSession();close();render();toast('备份已导入，替换前的数据可从恢复点找回')}}catch(err){toast('无法导入：'+err.message)}n.value=''}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,formId=form.getAttribute('id'),f=new FormData(form),v=Object.fromEntries(f);if(formId==='patient-form'){v.age=+v.age;v.score=+v.score;v.progress=+v.progress;v.name=v.name.trim();v.diagnosis=v.diagnosis.trim();if(!v.name||!v.diagnosis)return toast('请填写有效的代号和康复背景');if(form.dataset.edit==='true'){const changed=p().score!==v.score;Object.assign(p(),v);if(changed)db.assessments.push({id:uid('A'),patientId:selected,date:localDate(),score:v.score,wrist:null,grip:null,assessor:'档案编辑录入',notes:'在编辑档案时更新的总分，非自动评估。'})}else {const x={...v,id:uid('P'),baseline:v.score,device:'',color:'#edf5f0'};db.patients.push(x);selected=x.id;db.assessments.push({id:uid('A'),patientId:x.id,date:today,score:x.score,wrist:null,grip:null,assessor:'初始录入',notes:'初始档案记录，非软件评估。'})}save('保存体验档案');close();render();toast('档案已保存')}
 if(formId==='assessment-form'){if(!isDate(v.date)||v.date>today)return toast('评估日期须为有效日期，且不能晚于今天');db.assessments.push({...v,id:uid('A'),patientId:selected,score:+v.score,wrist:v.wrist?+v.wrist:null,grip:v.grip?+v.grip:null});const latest=db.assessments.filter(a=>a.patientId===selected).sort((a,b)=>a.date.localeCompare(b.date)).at(-1);p().score=latest.score;p().status='训练中';save('录入量表总分');close();render();toast('评估记录已保存')}
 if(formId==='note-form'||formId==='feedback-form'){if(!v.text.trim())return toast('请填写记录内容');db.notes.push({id:uid('N'),patientId:selected,date:when(),text:v.text.trim()});save('保存照护备注');close();render();toast('备注已保存')}
 if(formId==='plan-form'){const old=db.plans.find(x=>x.id===form.dataset.id);const d={...v,minutes:+v.minutes,intensity:+v.intensity,status:'待审核'};if(old)Object.assign(old,d);else db.plans.push({...d,id:uid('PLAN'),patientId:selected,date:when()});save('保存待审核方案');close();render();toast('草稿已保存，等待体验审核')}
 if(formId==='review-form'){const d=db.plans.find(x=>x.id===form.dataset.id);if(d)Object.assign(d,v,{status:e.submitter?.value||'已退回',reviewDate:when()});save('完成方案体验审核');close();render();toast('审核记录已保存')}
 if(formId==='report-review-form'){const r=db.reports.find(x=>x.id===form.dataset.id);Object.assign(r,v,{status:'已复核',reviewDate:when()});save('完成报告体验复核');close();render();showReport(r.id)}
 if(formId==='device-form'){const existing=db.devices.find(x=>x.id===v.id);if(!form.dataset.id&&existing)return toast('此设备编号已经存在，请使用重新绑定');if(v.patientId){db.devices.forEach(d=>{if(d.patientId===v.patientId&&d.id!==v.id)d.patientId=''});}db.patients.forEach(x=>{if(x.device===v.id)x.device=''});if(v.patientId){const person=db.patients.find(x=>x.id===v.patientId);if(person)person.device=v.id}if(existing)Object.assign(existing,{name:v.name,patientId:v.patientId});else db.devices.push({...v,battery:100,status:'离线记录',firmware:'未记录',maintenance:[]});save('保存设备绑定');close();render();toast('设备资产关系已保存')}
 if(formId==='maintenance-form'){const d=db.devices.find(x=>x.id===form.dataset.id);d.maintenance.push({date:when(),text:v.text});d.status=v.status;save('记录设备维护');close();render();toast('维护记录已保存')}
 if(formId==='finish-form'){const target=session.patientId||selected;if(!db.patients.some(x=>x.id===target))return toast('训练档案已不存在，请重置');if(!session.seconds)return toast('此段训练已保存');const id=session.runId||uid('S');if(db.sessions.some(s=>s.id===id)){resetSession();close();render();return toast('这段训练已归档，无需重复保存')}const sl=db.sessions.length,nl=db.notes.length;db.sessions.push({id,patientId:target,date:session.startedDate||localDate(),time:when(),mode:session.mode,seconds:session.seconds,completion:Math.min(100,Math.round(session.seconds/(session.minutes*60)*100)),feeling:v.feeling,source:'浏览器模拟训练'});if(v.notes.trim())db.notes.push({id:uid('N'),patientId:target,date:when(),text:v.notes.trim()});if(!save('保存模拟训练记录')){db.sessions.splice(sl);db.notes.splice(nl);return}resetSession();close();render();toast('训练与感受已保存到档案')}

 if(formId==='chat-form'){const q=v.question.trim();if(q)ask(q)}
 if(formId==='message-form'){if(!v.text.trim())return;db.messages.push({id:uid('M'),patientId:selected,date:when(),from:'体验用户',text:v.text.trim()});save('保存照护沟通记录');render();toast('沟通记录已保存在此浏览器')}
 if(formId==='task-form'||formId==='followup-form'){const person=formId==='followup-form'?v.patientId:selected;if(!db.patients.some(x=>x.id===person))return toast('请选择有效体验档案');if(!v.title.trim()||!isDate(v.date)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(v.time))return toast('请填写有效标题、日期与时间');const old=formId==='followup-form'?db.tasks.find(t=>t.id===form.dataset.id):null;const value={...v,title:v.title.trim(),notes:(v.notes||'').trim(),patientId:person,notified:false};if(old)Object.assign(old,value);else db.tasks.push({...value,id:uid('TASK'),done:false});calendarDay=v.date;calendarMonth=v.date.slice(0,7);save(old?'编辑随访安排':'创建随访安排');close();render();toast('随访已保存，可在随访计划中查看或导出日历')}
});
function canvasBase(id){const c=$('#'+id);if(!c)return null;const {width:w,height:h}=c.getBoundingClientRect();if(!w||!h)return null;const dpr=Math.min(2,window.devicePixelRatio||1);c.width=w*dpr;c.height=h*dpr;const ctx=c.getContext('2d');ctx.scale(dpr,dpr);ctx.font='9px Segoe UI,Microsoft YaHei,sans-serif';return {ctx,w,h}}
function drawLines(id,rows,sim=false){const base=canvasBase(id);if(!base)return;const{ctx,w,h}=base,l=37,r=w-12,t=10,b=h-25;ctx.lineWidth=1;ctx.strokeStyle='#eef2f2';ctx.fillStyle='#a5b2b4';const max=rows.reduce((m,row)=>Math.max(m,Math.abs(row[1]),Math.abs(row[2])),.01)*1.15;for(let i=0;i<5;i++){const y=t+(b-t)*i/4;ctx.beginPath();ctx.moveTo(l,y);ctx.lineTo(r,y);ctx.stroke();ctx.fillText((max-i*max/2).toFixed(2),0,y+3)}for(let i=0;i<6;i++){const x=l+(r-l)*i/5;ctx.fillText(((rows.at(-1)[0]-rows[0][0])*i/5000).toFixed(1)+'s',x-7,h-5)}const n=Math.max(80,Math.floor((r-l)*1.4)),step=Math.max(1,Math.floor(rows.length/n));for(let ch=1;ch<=2;ch++){ctx.strokeStyle=ch===1?'#68a58e':'#9eb2d2';ctx.globalAlpha=ch===1?1:.85;ctx.lineWidth=1.15;ctx.beginPath();for(let i=0;i<rows.length;i+=step){const x=l+(r-l)*(rows[i][0]-rows[0][0])/(rows.at(-1)[0]-rows[0][0]),y=t+(b-t)*(.5-rows[i][ch]/(2*max));if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.stroke()}ctx.globalAlpha=1}
function drawTrend(id,labels,values,color='#80b69f'){const base=canvasBase(id);if(!base)return;const{ctx,w,h}=base,l=30,r=w-13,t=12,b=h-29,max=Math.max(4,...values)*1.2;ctx.fillStyle='#a5b2b4';ctx.strokeStyle='#eef2f2';for(let i=0;i<5;i++){const y=t+(b-t)*i/4;ctx.beginPath();ctx.moveTo(l,y);ctx.lineTo(r,y);ctx.stroke();ctx.fillText(Math.round(max*(1-i/4)),1,y+3)}if(!values.length){ctx.fillStyle='#99aaa4';ctx.fillText('暂无评估数据',Math.max(l,w/2-36),h/2);return}const step=(r-l)/Math.max(1,values.length),bw=Math.min(28,step*.48);values.forEach((v,i)=>{const x=l+step*(i+.5),bh=v/max*(b-t);ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x-bw/2,b-bh,bw,bh,4);ctx.fill();if(values.length<=14||i%Math.ceil(values.length/7)===0){ctx.fillStyle='#9cacaf';ctx.fillText(labels[i],x-13,h-6)}})}
function charts(){if(view==='overview')drawLines('signal-chart',sampleRows(),true);if(view==='emg'&&emg)drawLines('emg-chart',emg.rows);if(view==='detail'){const assessments=db.assessments.filter(a=>a.patientId===selected).sort((a,b)=>a.date.localeCompare(b.date));drawTrend('progress-chart',assessments.map(a=>a.date.slice(5)),assessments.map(a=>a.score))}if(view==='analytics'){const dates=Array.from({length:range},(_,i)=>localDate(new Date(Date.now()-(range-1-i)*86400000))),values=dates.map(d=>db.sessions.filter(s=>s.date===d).length);drawTrend('analytics-chart',dates.map(d=>d.slice(5)),values);const since=dates[0],data=db.sessions.filter(s=>s.date>=since),n=data.length,a=data.filter(s=>s.mode==='主动助力').length/Math.max(1,n)*100,b=data.filter(s=>s.mode==='被动训练').length/Math.max(1,n)*100;$('#mode-donut').style.background=n?`conic-gradient(#75b69b 0 ${a}%,#92afd7 ${a}% ${a+b}%,#d1b98a ${a+b}% 100%)`:'#edf3ef'}}
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(charts,150)});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))close();if(e.target.closest('a[href^="#"]')){$('#sidebar')?.classList.remove('open');close()}});
setInterval(()=>{const previous=today;refreshDay();if(previous!==today)render();const now=new Date(),date=localDate(now),time=now.toLocaleTimeString('en-GB',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hour12:false});db.tasks.filter(t=>!t.done&&!t.notified&&(t.date<date||t.date===date&&t.time<=time)).forEach(t=>{toast('本地提醒：'+t.title);t.notified=true;save()})},15000);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&session.running){pause();render()}else if(!document.hidden){const previous=today;refreshDay();if(previous!==today)render()}});window.addEventListener('pagehide',()=>{if(session.running)pause();else saveSession()});
navigate();
